        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'df60f32d-7d4c-5003-91b9-46247d1d05c0', 0, 'EngineParameters', 'ConvertibleBond', 'Pricing.TimeStepsPerYear', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/EngineParameters/Parameter[@name=''Pricing.TimeStepsPerYear'']', 392, 'integer', true, 'Pricing time steps per year', 'The number of time steps per year to be used for the pricing PDE.', 'The number of time steps per year to be used for the pricing PDE.', '24', 'A number.', '1.8.10.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '289cc214-bdb1-5cfe-84fa-c0c870f3d68d', 0, 'EngineParameters', 'ConvertibleBond', 'SensitivityTemplate', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/EngineParameters/Parameter[@name=''SensitivityTemplate'']', 393, 'string', false, 'Sensitivity template', 'The sensitivity template of the product.', 'The sensitivity template of the product. The sensitivity configuration sets shift sizes and schemes for each template.', 'EQ_FD', 'The code of a sensitivity template.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '43555c85-ba7a-54b1-9d8e-0a79f06b0821', 0, 'ModelParameters', 'ConvertibleBond', 'AdjustCreditSpreadToRR', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/ModelParameters/Parameter[@name=''AdjustCreditSpreadToRR'']', 394, 'boolean', false, 'Adjust credit spread to RR', 'If true, the credit curve h(cdot) is adjusted by a factor frac1-R1-rho where R is the recovery rate associated to the market default curve and rho is the recovery rate of the bond.', 'If true, the credit curve h(cdot) is adjusted by a factor frac1-R1-rho where R is the recovery rate associated to the market default curve and rho is the recovery rate of the bond. Usually, R=rho, i.e. the bond recovery rate is the same as the recovery rate of the associated credit curve. In this case, the flag has no effect, since the multiplier is 1. However, when rho is overwritten with zero due to the flag ZeroRecoveryOverwrite set to true, the flag AdjustCreditSpreadToRR should also be set to true. The default value is false.', 'true', 'A choice from a fixed list, which its value set states.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fd1d0d25-fdaf-5eac-b3ec-a3236de6e138', 0, 'ModelParameters', 'ConvertibleBond', 'AdjustDiscounting', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/ModelParameters/Parameter[@name=''AdjustDiscounting'']', 395, 'boolean', false, 'Adjust discounting', 'If false, the adjustment of the discounting rate r to the benchmark curve b is suppressed, i.e.', 'If false, the adjustment of the discounting rate r to the benchmark curve b is suppressed, i.e. the change of the bond pricing PDE to the bond pricing pde with benchmark curve (see separate model documentation) is em not made (see also section "Curves used in practice" in separate model documentation). The default value is true.', 'false', 'A choice from a fixed list, which its value set states.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bb7ba327-c5b6-5d58-bb1a-b7de39e878dc', 0, 'ModelParameters', 'ConvertibleBond', 'AdjustEquityForward', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/ModelParameters/Parameter[@name=''AdjustEquityForward'']', 396, 'boolean', false, 'Adjust equity forward', 'If false, the term eta h(t,e^z) in the coefficient of v_z in the convertible bond pricing pde (see separate model documentation) is set to zero, i.e.', 'If false, the term eta h(t,e^z) in the coefficient of v_z in the convertible bond pricing pde (see separate model documentation) is set to zero, i.e. the hazard rate h is still used in the discounting term, but the equity drift is not corrected upwards accordingly. The default value is true.', 'true', 'A choice from a fixed list, which its value set states.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd02ca636-2f78-54e7-91a1-196f74e588de', 0, 'ModelParameters', 'ConvertibleBond', 'AdjustEquityVolatility', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/ModelParameters/Parameter[@name=''AdjustEquityVolatility'']', 397, 'boolean', false, 'Adjust equity volatility', 'If false, the market equity volatility input is not adjusted, but directly used in the pricing model.', 'If false, the market equity volatility input is not adjusted, but directly used in the pricing model. This setting is only possible if p=0. It will then set the weighting with the market survival probability S(0,t_i) in the context of formula for the equity volatility match (see separate model documentation) to zero, i.e. V is taken as the market implied volatility without adjustment. The default value is true.', 'false', 'A choice from a fixed list, which its value set states.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd1733797-bc07-55f3-90cf-abe17d6a6789', 0, 'ModelParameters', 'ConvertibleBond', 'TreatSecuritySpreadAsCreditSpread', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/ModelParameters/Parameter[@name=''TreatSecuritySpreadAsCreditSpread'']', 398, 'string', true, 'Treat security spread as credit spread', 'If true, the security spread is not incorporated into the benchmark curve b as described above, but rather added as a spread on top of the credit curve, i.e.', 'If true, the security spread is not incorporated into the benchmark curve b as described above, but rather added as a spread on top of the credit curve, i.e. it is added to h(t,e^z). For exchangeables, the security spread is added to em both h^B and h^S, i.e. it simultaneously increases the credit pread of both the equity and the bond component. Since the security spread is understood as an effective discounting spread, it is scaled by s rightarrow s / (1-rho) before it is added to h, where rho is the recovery rate of the bond.', 'true', 'A choice from a fixed list, which its value set states.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0f075a76-8bb4-501f-bba7-22a26ac4a540', 0, 'ModelParameters', 'ConvertibleBond', 'ZeroRecoveryOverwrite', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/ModelParameters/Parameter[@name=''ZeroRecoveryOverwrite'']', 399, 'boolean', false, 'Zero recovery overwrite', 'If true, the recovery rate rho of the convertible bond is overwritten with zero.', 'If true, the recovery rate rho of the convertible bond is overwritten with zero. This option is usually used in conjunction with AdjustCreditSpreadToRR set to true (see below). The default value is false.', 'true', 'A choice from a fixed list, which its value set states.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'def96cdd-a12a-5b2b-a86e-c9bbaf696747', 0, 'ModelParameters', 'ConvertibleBond', 'eta', 'ore.xsd', '/PricingEngines/Product[@type=''ConvertibleBond'']/ModelParameters/Parameter[@name=''eta'']', 400, 'double', true, 'Eta', 'The parameter eta of the model that links the stock price to the default intensity.', 'The parameter eta of the model that links the stock price to the default intensity.', '1.0', 'A number.', '1.8.7.0', null),
