        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f74e9a90-9968-5085-b60b-f3653602d1ae', 0, 'EngineParameters', 'IborRangeAccrualLeg', 'ByCallSpread', 'ore.xsd', '/PricingEngines/Product[@type=''IborRangeAccrualLeg'']/EngineParameters/Parameter[@name=''ByCallSpread'']', 726, 'boolean', false, 'By call spread', 'If true, the range accrual condition is priced using a call-spread approximation, which naturally incorporates the volatility smile (each spread leg is priced at its own strike vol).', 'If true, the range accrual condition is priced using a call-spread approximation, which naturally incorporates the volatility smile (each spread leg is priced at its own strike vol). If false, a Black--Scholes digital pricing is used: the digital value is computed analytically using the volatility at the strike, without accounting for the slope of the smile. Defaults to true if omitted. Allowable values: true, false.', 'true', 'A choice from a fixed list, which its value set states.', '1.8.16.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1eee5226-29c3-516e-9e9a-88e79b7e5a64', 0, 'EngineParameters', 'IborRangeAccrualLeg', 'CallSpreadEps', 'ore.xsd', '/PricingEngines/Product[@type=''IborRangeAccrualLeg'']/EngineParameters/Parameter[@name=''CallSpreadEps'']', 727, 'double', false, 'Call spread eps', 'The width of the call-spread in rate terms.', 'The width of the call-spread in rate terms. Smaller values approach the analytical digital; larger values smooth the replication. Defaults to 1E-4 (1 basis point) if omitted. Allowable values: Any positive real number.', '1E-4', 'A number.', '1.8.16.0', null),
