        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9fcc8945-8ed4-5249-b3fb-f380ecebce98', 0, 'GlobalParameters', '', 'BondFutureAmericanAsEuropean', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''BondFutureAmericanAsEuropean'']', 831, 'string', false, 'American bond future as European', 'Whether an American bond future option is priced as European.', 'It takes true, false or a regular expression. When it is true, every American bond future option is priced as though its exercise were European. When it is a regular expression, only the options whose underlying contract name matches it are. When it is false, the default, it has no effect.', 'false', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5efe90f4-e0ce-5900-afd2-d3b267ae8a23', 0, 'GlobalParameters', '', 'PseudoCurrency.TreatAsFX', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''PseudoCurrency.TreatAsFX'']', 832, 'boolean', false, 'Pseudo-currency: treat as FX', 'Whether the pseudo-currency market is treated as an FX market.', 'It passes through to the pure FX handling of the pseudo-currency. With no global parameters, ORE treats the pseudo-currency as FX.', 'true', 'A flag, written true or false.', '1.8.13.0', null),
