        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eae4e774-2ab7-561b-bfdb-961454d50ca4', 0, 'GlobalParameters', '', 'PseudoCurrency.Curve.XAU', 'ore.xsd', '/PricingEngines/GlobalParameters/Parameter[@name=''PseudoCurrency.Curve.XAU'']', 835, 'string', false, 'Pseudo-currency curve for gold', 'The curve that prices the pseudo-currency XAU.', 'It maps the three-letter code XAU to the curve that prices it, such as PM:XAUUSD.', 'PM:XAUUSD', 'Text.', '1.8.13.0', null),
