        (v_dataset_id, ores_utility_system_tenant_id_fn(), '506ddb18-09ab-5538-9f76-f23171af6628', 0, 'Engines', '', 'AnalyticDiscreteGeometricAPEngine', 'ore.xsd', '/PricingEngines/Product/Engine[@name=''AnalyticDiscreteGeometricAPEngine'']', 877, 'string', false, 'AnalyticDiscreteGeometricAPEngine', 'Closed-form price of a discrete geometric average price Asian option.', 'The average is the geometric mean over fixing dates, which gives a closed formula.', 'The name of a pricing engine.', 'The name of a pricing engine.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bff672ef-30c5-5ffd-9f07-978433bc7327', 0, 'Engines', '', 'AnalyticDiscreteGeometricASEngine', 'ore.xsd', '/PricingEngines/Product/Engine[@name=''AnalyticDiscreteGeometricASEngine'']', 878, 'string', false, 'AnalyticDiscreteGeometricASEngine', 'Closed-form price of a discrete geometric average strike Asian option.', 'The strike is the geometric mean over fixing dates, which gives a closed formula.', 'The name of a pricing engine.', 'The name of a pricing engine.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7ea995d9-cd92-5412-ad89-bcdfb63bbaf2', 0, 'Engines', '', 'AnalyticDoubleBarrierBinaryEngine', 'ore.xsd', '/PricingEngines/Product/Engine[@name=''AnalyticDoubleBarrierBinaryEngine'']', 879, 'string', false, 'AnalyticDoubleBarrierBinaryEngine', 'Closed-form price of a double barrier binary option.', 'Prices a digital option that knocks in or out at an upper and a lower barrier.', 'The name of a pricing engine.', 'The name of a pricing engine.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5668b286-48fd-5529-be04-06c4c32ab16c', 0, 'Engines', '', 'AnalyticDoubleBarrierEngine', 'ore.xsd', '/PricingEngines/Product/Engine[@name=''AnalyticDoubleBarrierEngine'']', 880, 'string', false, 'AnalyticDoubleBarrierEngine', 'Closed-form price of a double barrier option.', 'Prices a vanilla option that knocks in or out at an upper and a lower barrier, with the Ikeda-Kunitomo series.', 'The name of a pricing engine.', 'The name of a pricing engine.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '121827fb-ecaf-5f6d-b650-f7f507697879', 0, 'Engines', '', 'AnalyticEuropeanEngine', 'ore.xsd', '/PricingEngines/Product/Engine[@name=''AnalyticEuropeanEngine'']', 881, 'string', false, 'AnalyticEuropeanEngine', 'Closed-form Black-Scholes price of a European option.', 'Prices a European option with the Black-Scholes formula for the model of the pair.', 'The name of a pricing engine.', 'The name of a pricing engine.', '1.8.7.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b61a97bf-5427-5ca4-8c80-5dcfe2da97f8', 0, 'Engines', '', 'AnalyticEuropeanForwardEngine', 'ore.xsd', '/PricingEngines/Product/Engine[@name=''AnalyticEuropeanForwardEngine'']', 882, 'string', false, 'AnalyticEuropeanForwardEngine', 'Closed-form price of an option on a forward.', 'Prices a European option on a forward or future with the Black formula. The underlying is the forward and not the spot.', 'The name of a pricing engine.', 'The name of a pricing engine.', '1.8.13.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd41860a3-e2bf-5bef-809d-c4353ce04be0', 0, 'Engines', '', 'AnalyticalApproximation', 'ore.xsd', '/PricingEngines/Product/Engine[@name=''AnalyticalApproximation'']', 883, 'string', false, 'AnalyticalApproximation', 'Analytical approximation for average price options.', 'Builds a CommodityAveragePriceOptionAnalyticalEngine. The setting Volatility selects the model for the average.', 'The name of a pricing engine.', 'The name of a pricing engine.', '1.8.8.0', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e7ec53c7-44d1-598f-938d-c8db28a99153', 0, 'Engines', '', 'BaroneAdesiWhaleyApproximationEngine', 'ore.xsd', '/PricingEngines/Product/Engine[@name=''BaroneAdesiWhaleyApproximationEngine'']', 884, 'string', false, 'BaroneAdesiWhaleyApproximationEngine', 'Barone-Adesi and Whaley approximation for American options.', 'A quick analytic approximation of the early exercise premium of an American option.', 'The name of a pricing engine.', 'The name of a pricing engine.', '1.8.13.0', null),
