        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3380c6eb-1461-5b9b-8255-924064e057d7', 0, 'Pairs', 'SyntheticCDO', 'GaussCopula|Bucketing', 'ore.xsd', '/PricingEngines/Product[@type=''SyntheticCDO'']/Model[@name=''GaussCopula'']/Engine[@name=''Bucketing'']', 1146, 'string', false, 'GaussCopula / Bucketing', 'Builds a IndexCdsTrancheEngine.It uses a Bucketing Algorithm to compute the expected tranche loss.', 'Builds a IndexCdsTrancheEngine.It uses a Bucketing Algorithm to compute the expected tranche loss.', 'The usual pair.', 'The model and engine that price SyntheticCDO together.', '1.8.7.0', null),
