        (v_dataset_id, ores_utility_system_tenant_id_fn(), '372bffa1-d659-5269-aa78-e70099560938', 0, 'Pairs', 'YYCapFloor', 'YYCapModel|YYCapEngine', 'ore.xsd', '/PricingEngines/Product[@type=''YYCapFloor'']/Model[@name=''YYCapModel'']/Engine[@name=''YYCapEngine'']', 1148, 'string', false, 'YYCapModel / YYCapEngine', 'Builds a YoYInflationBlackCapFloorEngine, YoYInflationUnitDisplacedBlackCapFloorEngine, YoYInflationBachelierCapFloorEngine depending on the volatility type of the market surface.', 'Builds a YoYInflationBlackCapFloorEngine, YoYInflationUnitDisplacedBlackCapFloorEngine, YoYInflationBachelierCapFloorEngine depending on the volatility type of the market surface.', 'The usual pair.', 'The model and engine that price YYCapFloor together.', '1.8.7.0', null),
