        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c3ec376a-d4e4-5478-96b6-d8b5a46bfcbf', 0, 'BondYield', '', 'Id', 'conventions.xsd', '/Conventions/BondYield/Id', 0, 'string', true, 'Id', 'The constant maturity index index name.', 'The constant maturity index index name. This must be of the form "CMB-FAMILY-TENOR" where FAMILY can consist of any number of tags separated by "-"', 'None: the convention must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '48e2e465-7cfd-5e94-8f50-5f55987819a1', 0, 'BondYield', '', 'Compounding', 'conventions.xsd', '/Conventions/BondYield/Compounding', 1, 'string', true, 'Compounding', 'Compounding of the yield - Simple, Compounded, Continuous, SimpleThenCompounded', 'Compounding of the yield - Simple, Compounded, Continuous, SimpleThenCompounded', 'None: the convention must give it.', 'A compounding rule, such as Simple or Compounded.', '1.8.0.7 or earlier', null),
