        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a631f754-a0f8-58a1-819e-afcb30fb8fcb', 0, 'CDS', '', 'Id', 'conventions.xsd', '/Conventions/CDS/Id', 0, 'string', true, 'Id', 'The identifier for the CDS convention.', 'The identifier for the CDS convention.', 'None: the convention must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1b628729-2311-5e1c-9d4d-48d96ce2c589', 0, 'CDS', '', 'SettlesAccrual', 'conventions.xsd', '/Conventions/CDS/SettlesAccrual', 2, 'boolean', true, 'Settles accrual', 'A boolean value indicating if an accrued fee is due on the occurrence of a credit event.', 'A boolean value indicating if an accrued fee is due on the occurrence of a credit event. Allowable boolean values are given in the Table the guide. In general, this is set true.', 'None: the convention must give it.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '281a3b6b-593d-566d-8557-72031452c56c', 0, 'CDS', '', 'PaysAtDefaultTime', 'conventions.xsd', '/Conventions/CDS/PaysAtDefaultTime', 3, 'boolean', true, 'Pays at default time', 'A boolean value indicating if the accrued fee, on the occurrence of a credit event, is payable at the credit event date or the end of the fee period.', 'A boolean value indicating if the accrued fee, on the occurrence of a credit event, is payable at the credit event date or the end of the fee period. A value of true indicates that the accrued is payable at the credit event date and a value of false indicates that it is payable at the end of the fee period. In general, this is set true.', 'None: the convention must give it.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '901fccc4-2251-534a-b27b-d687f3cc9466', 0, 'CDS', '', 'SettlementDays', 'conventions.xsd', '/Conventions/CDS/SettlementDays', 5, 'string', false, 'Settlement days', 'The number of days after the CDS trade date when protection starts i.e.\ the Protection effective date or step-in date.', 'The number of days after the CDS trade date when protection starts i.e.\ the Protection effective date or step-in date. Any non-negative integer is allowed here. For standard CDS after, this is generally set to 1.', 'None where the convention needs it; the description says when.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bfb8808e-d43f-501f-90fa-0dcef02c3acd', 0, 'CDS', '', 'Calendar', 'conventions.xsd', '/Conventions/CDS/Calendar', 6, 'string', false, 'Calendar', 'The calendar associated with the CDS.', 'The calendar associated with the CDS. For non-JPY currencies, this is generally WeekendsOnly to agree with the ISDA standard. For JPY CDS, the ISDA standard calendar is TYO documented at \url{https://www.cdsmodel.com/cdsmodel}. This could be set up as an additional calendar or JPN could be used as a proxy. Allowable calendar values are given in Table the guide.', 'None where the convention needs it; the description says when.', 'A calendar, such as TARGET or US-NYSE.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2ebe0eba-44b4-5e61-8d63-3d156b96aba0', 0, 'CDS', '', 'Frequency', 'conventions.xsd', '/Conventions/CDS/Frequency', 7, 'string', false, 'Frequency', 'The frequency of fee leg payments for the CDS.', 'The frequency of fee leg payments for the CDS. The ISDA standard is Quarterly but any valid frequency is allowed.', 'None where the convention needs it; the description says when.', 'A frequency, such as Annual or Quarterly.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '39f2f587-61a9-5aa7-81de-3bf51dac68a6', 0, 'CDS', '', 'PaymentConvention', 'conventions.xsd', '/Conventions/CDS/PaymentConvention', 8, 'string', false, 'Payment convention', 'The business day convention for payments on the CDS.', 'The business day convention for payments on the CDS. The ISDA standard is Following but any valid business day convention from Table the guide is allowed.', 'None where the convention needs it; the description says when.', 'A business day convention, such as ModifiedFollowing or F.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ba7a3a80-bf19-5177-a876-d99243b55238', 0, 'CDS', '', 'Rule', 'conventions.xsd', '/Conventions/CDS/Rule', 9, 'string', false, 'Rule', 'The date generation rule for the fee leg on the CDS.', 'The date generation rule for the fee leg on the CDS. The ISDA standard is CDS2015 but any valid date generation rule is allowed.', 'None where the convention needs it; the description says when.', 'A date generation rule, such as Backward.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b515f827-d275-5820-a954-49fac8cb282e', 0, 'CDS', '', 'DayCounter', 'conventions.xsd', '/Conventions/CDS/DayCounter', 10, 'string', false, 'Day counter', 'The day counter for fee leg payments on the CDS.', 'The day counter for fee leg payments on the CDS. The ISDA standard is A360 but any valid day counter from Table the guide is allowed.', 'None where the convention needs it; the description says when.', 'A day counter, such as A360 or ACT/365.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7dd2f52e-ba51-56a9-8d75-016bda0731e5', 0, 'CDS', '', 'LastPeriodDayCounter', 'conventions.xsd', '/Conventions/CDS/LastPeriodDayCounter', 11, 'string', false, 'Last period day counter', 'The day counter for the last fee leg payment on the CDS.', 'The day counter for the last fee leg payment on the CDS. The ISDA standard is A360 (Incl Last) but any valid day counter from Table the guide is allowed. If not given, the following fallback rule applies: If DayCounter is A360, LastPeriodDayCounter is set to A360 (Incl Last), otherwise LastPeriodDayCounter is set to the same value as DayCounter.', 'Not given: ORE applies its own rule.', 'A day counter, such as A360 or ACT/365.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a2998368-723e-5307-8b92-2f2f0a477c80', 0, 'CmsSpreadOption', '', 'Id', 'conventions.xsd', '/Conventions/CmsSpreadOption/Id', 0, 'string', true, 'Identifier', 'The unique identifier of the convention.', 'The unique identifier of the convention. A curve segment, a quote or another convention refers to the convention by it.', 'None: the convention must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b456b213-1060-57b6-9f62-1f8fd8718e0f', 0, 'CmsSpreadOption', '', 'ForwardStart', 'conventions.xsd', '/Conventions/CmsSpreadOption/ForwardStart', 1, 'string', true, 'Forward start', 'The calendar for the fixed rate leg of the swap.', 'The calendar for the fixed rate leg of the swap.', 'None: the convention must give it.', 'A period, such as 2D or 3M.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '541be4f0-f91a-5ffb-8b9c-d1f74f242e3d', 0, 'CmsSpreadOption', '', 'SpotDays', 'conventions.xsd', '/Conventions/CmsSpreadOption/SpotDays', 2, 'string', true, 'Spot days', 'The number of business days to spot for the CMS Spread Index.', 'The number of business days to spot for the CMS Spread Index.', 'None: the convention must give it.', 'A period, such as 2D or 3M.', '1.8.0.7 or earlier', null),
