        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fe9e1718-576b-5ae0-9a2d-0b92f4efef1f', 0, 'CmsSpreadOption', '', 'DayCounter', 'conventions.xsd', '/Conventions/CmsSpreadOption/DayCounter', 6, 'string', true, 'Day counter', 'The day counter for the CMS Spread leg.', 'The day counter for the CMS Spread leg.', 'None: the convention must give it.', 'A day counter, such as A360 or ACT/365.', '1.8.0.7 or earlier', null),
