        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4da99181-959f-5d88-b2bb-761b63e97088', 0, 'CommodityForward', '', 'Id', 'conventions.xsd', '/Conventions/CommodityForward/Id', 0, 'string', true, 'Id', 'The identifier for the commodity forward convention.', 'The identifier for the commodity forward convention. The identifier here should match the Name that would be provided for the commodity in the trade XML as described in Table the guide.', 'None: the convention must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cea42be4-b32c-519f-b42c-e29f1bb178c8', 0, 'CommodityForward', '', 'SpotDays', 'conventions.xsd', '/Conventions/CommodityForward/SpotDays', 1, 'string', false, 'Spot days', 'The number of business days to spot for the commodity.', 'The number of business days to spot for the commodity. Any non-negative integer is allowed here. If omitted, this takes a default value of 2.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1a237949-7be3-5531-8f0c-15dc3ee24bdf', 0, 'CommodityForward', '', 'PointsFactor', 'conventions.xsd', '/Conventions/CommodityForward/PointsFactor', 2, 'double', false, 'Points factor', 'This is only used if Outright is false.', 'This is only used if Outright is false. Any positive real number is allowed here. When Outright is false, the commodity forward quotes are provided as points i.e. a number that should be added to the commodity spot to give the outright commodity forward rate. The PointsFactor is the number by which the points quote should be divided before adding it to the spot quote to obtain the forward price. If omitted, this takes a default value of 1.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6fc7e78f-c6ff-5b80-89bd-3885ea8c0456', 0, 'CommodityForward', '', 'AdvanceCalendar', 'conventions.xsd', '/Conventions/CommodityForward/AdvanceCalendar', 3, 'string', false, 'Advance calendar', 'The business day calendar(s) used for advancing dates for both spot and forwards.', 'The business day calendar(s) used for advancing dates for both spot and forwards. The allowable values are given in Table the guide. If omitted, it defaults to NullCalendar i.e. a calendar where all days are considered good business days.', 'NullCalendar i.e. a calendar where all days are considered good business days.', 'A calendar, such as TARGET or US-NYSE.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e99348e5-4a9d-5b91-94b4-f225d0217b8c', 0, 'CommodityForward', '', 'SpotRelative', 'conventions.xsd', '/Conventions/CommodityForward/SpotRelative', 4, 'boolean', false, 'Spot relative', 'The allowable values are true and false.', 'The allowable values are true and false. If true, the forward tenor is interpreted as being relative to the spot date. If false, the forward tenor is interpreted as being relative to the valuation date. If omitted, it defaults to True.', 'True.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '21188120-d608-52bb-adcf-ac64ac38c1cf', 0, 'CommodityForward', '', 'DeliveryLocation', 'conventions.xsd', '/Conventions/CommodityForward/DeliveryLocation', 5, 'string', false, 'Delivery location', 'Delivery location or delivery basis identifier for the commodity contract (for example, XCEC, XLME, PM).', 'Delivery location or delivery basis identifier for the commodity contract (for example, XCEC, XLME, PM). When provided, this value is used by FRTB commodity delta CRIF generation as Label2.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3b2a2125-2d04-5662-83fd-aae1b1095668', 0, 'CommodityForward', '', 'BusinessDayConvention', 'conventions.xsd', '/Conventions/CommodityForward/BusinessDayConvention', 6, 'string', false, 'Business day convention', 'The business day roll convention used to adjust dates when getting from the valuation date to the spot date and the forward maturity date.', 'The business day roll convention used to adjust dates when getting from the valuation date to the spot date and the forward maturity date. The allowable values are given in Table the guide. If omitted, it defaults to Following.', 'Following.', 'A business day convention, such as ModifiedFollowing or F.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd2942c81-ba77-50a3-8437-b7f57404a3be', 0, 'CommodityForward', '', 'Outright', 'conventions.xsd', '/Conventions/CommodityForward/Outright', 7, 'boolean', false, 'Outright', 'The allowable values are true and false.', 'The allowable values are true and false. If true, the forward quotes are interpreted as outright forward prices. If false, the forward quotes are interpreted as points i.e. as a number that must be added to the spot price to get the outright forward price. If omitted, it defaults to true.', 'true.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8e065ef0-e671-53e9-aa60-cd020b743c9a', 0, 'CommodityFuture', '', 'Id', 'conventions.xsd', '/Conventions/CommodityFuture/Id', 0, 'string', true, 'Id', 'The identifier for the commodity future convention.', 'The identifier for the commodity future convention. The identifier here should match the Name that would be provided for the commodity in the trade XML as described in Table the guide.', 'None: the convention must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9f1f8cc1-edfb-52f9-988d-094d5643d06a', 0, 'CommodityFuture', '', 'ContractFrequency', 'conventions.xsd', '/Conventions/CommodityFuture/ContractFrequency', 1, 'string', true, 'Contract frequency', 'This node indicates the frequency of the commodity future contracts.', 'This node indicates the frequency of the commodity future contracts. The value here is usually Monthly or Quarterly, but allowed values are Daily, Weekly, Monthly, Quaterly and Annual.', 'None: the convention must give it.', 'A frequency, such as Annual or Quarterly.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '96884dfa-4268-5d34-951c-8b8807bf12f5', 0, 'CommodityFuture', '', 'OptionContractFrequency', 'conventions.xsd', '/Conventions/CommodityFuture/OptionContractFrequency', 2, 'string', false, 'Option contract frequency', 'This node indicates the frequency of the commodity future options if it differs from the frequency of the underlying future contract.', 'This node indicates the frequency of the commodity future options if it differs from the frequency of the underlying future contract. The value here is usually Monthly', 'Not given: ORE applies its own rule.', 'A frequency, such as Annual or Quarterly.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '18a5cf82-db2b-5cf0-9005-60cafe45cdb8', 0, 'CommodityFuture', '', 'Calendar', 'conventions.xsd', '/Conventions/CommodityFuture/Calendar', 10, 'string', true, 'Calendar', 'The business day trading calendar(s) applicable for the commodity future contract.', 'The business day trading calendar(s) applicable for the commodity future contract.', 'None: the convention must give it.', 'A calendar, such as TARGET or US-NYSE.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '30944b61-b63a-5cc8-8c59-4190cd365ea6', 0, 'CommodityFuture', '', 'ExpiryCalendar', 'conventions.xsd', '/Conventions/CommodityFuture/ExpiryCalendar', 11, 'string', false, 'Expiry calendar', 'The business day expiry calendar(s) applicable for the commodity future contract.', 'The business day expiry calendar(s) applicable for the commodity future contract. This calendar is used when deriving expiry dates. If omitted, this defaults to the trading day calendar specified in the Calendar node.', 'the trading day calendar specified in the Calendar node.', 'A calendar, such as TARGET or US-NYSE.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3c9dd208-8659-5ac0-be2f-cf3fcfb4cf60', 0, 'CommodityFuture', '', 'ExpiryMonthLag', 'conventions.xsd', '/Conventions/CommodityFuture/ExpiryMonthLag', 12, 'integer', false, 'Expiry month lag', 'The allowable values are any integer.', 'The allowable values are any integer. This value indicates the number of months from the month containing the expiry date to the contract month. If 0, the commodity future contract expiry date is in the contract month. If the value of ExpiryMonthLag is n > 0, the commodity future contract expires in the n-th month prior to the contract month. If the value of ExpiryMonthLag is n < 0, the commodity future contract expires in the n-th month after the contract month. The value of ExpiryMonthLag is generally 0, 1 or 2. For example, NYMEX:CL has an ExpiryMonthLag of 1 and ICE:B has an ExpiryMonthLag of 2. If omitted, it defaults to 0.', '0.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e875aa78-396d-5b62-af40-4ab89bc96a67', 0, 'CommodityFuture', '', 'OneContractMonth', 'conventions.xsd', '/Conventions/CommodityFuture/OneContractMonth', 13, 'string', false, 'One contract month', 'This node takes a calendar month in the form of the first three characters of the month with the first character capitalised.', 'This node takes a calendar month in the form of the first three characters of the month with the first character capitalised. The month provided should be an arbitrary valid future contract month. It is used in cases where the ContractFrequency is not Monthly in order to determine the valid contract months. If omitted, it defaults to January.', 'January.', 'A month, such as Jan.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1ddc762d-cf21-50ce-aaaa-1186aa7dcdc6', 0, 'CommodityFuture', '', 'OffsetDays', 'conventions.xsd', '/Conventions/CommodityFuture/OffsetDays', 14, 'string', false, 'Offset days', 'The number of business days that the expiry date is before the base date where the base date is implied by the AnchorDay node above.', 'The number of business days that the expiry date is before the base date where the base date is implied by the AnchorDay node above. Any non-negative integer is allowed here. If omitted, this takes a default value of zero.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b964a45e-8c7c-5ff6-ba6c-60e183fc25e2', 0, 'CommodityFuture', '', 'BusinessDayConvention', 'conventions.xsd', '/Conventions/CommodityFuture/BusinessDayConvention', 15, 'string', false, 'Business day convention', 'The business day roll convention used to adjust the expiry date.', 'The business day roll convention used to adjust the expiry date. The allowable values are given in Table the guide. If omitted, it defaults to Preceding.', 'Preceding.', 'A business day convention, such as ModifiedFollowing or F.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f1e59bf2-d4e7-5e93-97c2-7956027afd4e', 0, 'CommodityFuture', '', 'AdjustBeforeOffset', 'conventions.xsd', '/Conventions/CommodityFuture/AdjustBeforeOffset', 16, 'boolean', false, 'Adjust before offset', 'The allowable values are true and false.', 'The allowable values are true and false. If true, if the base date implied by the AnchorDay node above is not a good business day according to the calendar provided in the Calendar node, this date is adjusted before the offset specified in the OffsetDays is applied. If false, this adjustment does not happen. If omitted, it defaults to true.', 'true.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8392003b-2a57-5ee8-a17f-5302463b553c', 0, 'CommodityFuture', '', 'IsAveraging', 'conventions.xsd', '/Conventions/CommodityFuture/IsAveraging', 17, 'boolean', false, 'Is averaging', 'The allowable values are true and false.', 'The allowable values are true and false. This node indicates if the future contract is based on the average commodity price of the contract period. If omitted, it defaults to false.', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5a206112-103b-5a9c-a3c3-35f84803a837', 0, 'CommodityFuture', '', 'OptionExpiryMonthLag', 'conventions.xsd', '/Conventions/CommodityFuture/OptionExpiryMonthLag', 18, 'integer', false, 'Option expiry month lag', 'The allowable values are any integer.', 'The allowable values are any integer. This value indicates the number of months from the month containing the option expiry date to the month containing the expiry date. If 0, the commodity future option contract expiry date is anchored in the same month as the commodity future contract expiry date. If the value of OptionExpiryMonthLag is n > 0, the commodity option future contract expires in the n-th month prior to the commodity future contract expiry month. If the value of OptionExpiryMonthLag is n < 0, the commodity option future contract expires in the n-th month after the commodity future contract expiry month. The value of OptionExpiryMonthLag should be equal to ExpiryMonthLag when OptionExpiryOffset is used. The OptionExpiryMonthLag is rarely used. An example is the Crude Palm Oil contract XKLS:FCPO where the future contract expiry is in the delivery month and the option expiry is in the month that is 2 months prior to this. In this case, OptionExpiryMonthLag is 2. If omitted, OptionExpiryMonthLag defaults to 0.', '0.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e02551f8-c18b-5a77-97d5-706a91e2c6dd', 0, 'CommodityFuture', '', 'OptionExpiryOffset', 'conventions.xsd', '/Conventions/CommodityFuture/OptionExpiryOffset', 19, 'string', false, 'Option expiry offset', 'The number of business days that the option expiry date is before the future expiry date.', 'The number of business days that the option expiry date is before the future expiry date. Any non-negative integer is allowed here. If omitted, this takes a default value of zero and the expiry date of an option on the future contract is assumed to equal the expiry date of the future contract.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '337366d2-63fe-542c-b66b-6ac8fa870c3c', 0, 'CommodityFuture', '', 'OptionExpiryDay', 'conventions.xsd', '/Conventions/CommodityFuture/OptionExpiryDay', 20, 'string', false, 'Option expiry day', 'This node can contain any integer in the range 1,\ldots,31 indicating the day of the month on which an option expiry date is anchored.', 'This node can contain any integer in the range 1,\ldots,31 indicating the day of the month on which an option expiry date is anchored. A value of 31 will guarantee that the last day in the month is used a base date. If omitted, this is not used. Setting this field takes precedence over OptionExpiryOffset.\item OptionBusinessDayConvention [Optional]: The business day convention used to adjust the option expiry date to a good business day if OptionExpiryDay is used.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9bdcbf8e-ad59-54f1-9fb9-7a0ba3f5b07f', 0, 'CommodityFuture', '', 'OptionExpiryLastWeekdayOfMonth', 'conventions.xsd', '/Conventions/CommodityFuture/OptionExpiryLastWeekdayOfMonth', 23, 'string', false, 'Option expiry last weekday of month', 'This node is used to indicate a date in a given month in the form of the last named weekday of that month e.g.', 'This node is used to indicate a date in a given month in the form of the last named weekday of that month e.g. last Wednesday. The node takes a weekday in the form of the first three characters of the weekday with the first character capitalised.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'db781571-1a10-5b9b-8641-da3e7925f9db', 0, 'CommodityFuture', '', 'OptionExpiryWeeklyDayOfTheWeek', 'conventions.xsd', '/Conventions/CommodityFuture/OptionExpiryWeeklyDayOfTheWeek', 24, 'string', false, 'Option expiry weekly day of the week', 'This node is used to indicate a date in a given week in the form of the named weekday, e.g.', 'This node is used to indicate a date in a given week in the form of the named weekday, e.g. Wednesday. The node takes a weekday in the form of the first three characters of the weekday with the first character capitalised. This node is mandatory for weekly expiring options. The node is not allowed to use with any other option contract frequency.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5968b299-ef39-5320-a5a5-b14c6e472736', 0, 'CommodityFuture', '', 'OptionCalendarDaysBefore', 'conventions.xsd', '/Conventions/CommodityFuture/OptionCalendarDaysBefore', 25, 'string', false, 'Option calendar days before', 'This node can contain any non-negative integer.', 'This node can contain any non-negative integer. The option expiry date is this number of calendar days before the first calendar day of the contract month.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a2a17231-4745-5d16-a178-25071746837b', 0, 'CommodityFuture', '', 'OptionMinBusinessDaysBefore', 'conventions.xsd', '/Conventions/CommodityFuture/OptionMinBusinessDaysBefore', 26, 'string', false, 'Option min business days before', 'This node can contain any non-negative integer.', 'This node can contain any non-negative integer. The option expiry date is this at least this number of business days before the contract expiry. The option expiry date is calculated using the regular rule and if the option expiry date falls on a date before this minimum date, the minimum date will be taken instead.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8da4c67a-3cfb-5cc2-a780-666383e4945f', 0, 'CommodityFuture', '', 'OptionBusinessDayConvention', 'conventions.xsd', '/Conventions/CommodityFuture/OptionBusinessDayConvention', 27, 'string', false, 'Option business day convention', 'The business day convention used to adjust the option expiry date to a good business day if OptionExpiryDay is used.', 'The business day convention used to adjust the option expiry date to a good business day if OptionExpiryDay is used.', 'Not given: ORE applies its own rule.', 'A business day convention, such as ModifiedFollowing or F.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '76aa8db6-539f-50cb-a9e0-95e996a7a94b', 0, 'CommodityFuture', '', 'FutureContinuationMappings', 'conventions.xsd', '/Conventions/CommodityFuture/FutureContinuationMappings', 28, 'string', false, 'Future continuation mappings', 'When building future curves, we may use market data that has a continuation expiry, i.e.', 'When building future curves, we may use market data that has a continuation expiry, i.e. c1, c2, etc. , as opposed to an explicit expiry date or tenor. In some cases, the continuation expiries coming from the market data provider may skip serial months and therefore we use the mapping here to map from the market data provider index to the relevant serial month.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ae2d4e1a-65d4-5a90-a3c7-38a40c3eab1f', 0, 'CommodityFuture', '', 'OptionContinuationMappings', 'conventions.xsd', '/Conventions/CommodityFuture/OptionContinuationMappings', 29, 'string', false, 'Option continuation mappings', 'When building option volatility structures, we may use market data that has a continuation expiry, i.e.', 'When building option volatility structures, we may use market data that has a continuation expiry, i.e. c1, c2, etc. , as opposed to an explicit expiry date or tenor. In some cases, the continuation expiries coming from the market data provider may skip serial months and therefore we use the mapping here to map from the market data provider index to the relevant serial month. For example, for the Crude Palm Oil contract XKLS:FCPO, the option expiry months are serial up to the 9th month and then alternate months. So, we would add a mapping from 10 to 11, 11 to 13 and so on so that the correct option expiry is arrived at when reading the market data quotes and constructing the option volatility structure.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8a60e0a1-3474-554e-8c16-1ca2bc6b1acf', 0, 'CommodityFuture', '', 'HoursPerDay', 'conventions.xsd', '/Conventions/CommodityFuture/HoursPerDay', 30, 'integer', false, 'Hours per day', 'For power derivatives, quantities are sometimes given as a quantity per hour.', 'For power derivatives, quantities are sometimes given as a quantity per hour. To deduce the quantity for the day which is multiplied by that day''s future price, one needs to know the number of hours in the day associated with the future price. For example ICE PDQ is the daily PJM Western Hub Real Time Peak future contract. The price each day for this contract is the average of the locational marginal prices (LMPs) for all hours ending 08:00 to 23:00 Eastern Pacific Time. In other words, there are 16 hours in the day that feed in to the average yielding this settlement price. For this contract, HoursPerDay would be 16. This field is only needed if a trade XML references this commodity contract, has CommodityQuantityFrequency set to PerHour and has no HoursPerDay value set directly in the XML.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '58965467-5ac2-5910-ab1e-3c2a2b5c40ad', 0, 'CommodityFuture', '', 'SavingsTime', 'conventions.xsd', '/Conventions/CommodityFuture/SavingsTime', 32, 'string', false, 'Savings time', 'For some derivatives, quantities are given as quantity per calendar day and hour.', 'For some derivatives, quantities are given as quantity per calendar day and hour. The monthly quantity is then scaled by the number of calendar days times hours per day (see above) plus or minus a daylight savings correction. To compute the daylight savings correction a convention is needed that describes the dates on which dates one hour is gained resp. lost. Currently supported conventions are US, Null. Default is US if no convention is given.', 'US if no convention is given.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd7a11086-a949-5311-9941-901ec643bab2', 0, 'CommodityFuture', '', 'DeliveryLocation', 'conventions.xsd', '/Conventions/CommodityFuture/DeliveryLocation', 33, 'string', false, 'Delivery location', 'Delivery location or delivery basis identifier for the commodity contract.', 'Delivery location or delivery basis identifier for the commodity contract. When provided, this value is used by FRTB commodity delta CRIF generation as Label2 for commodity sensitivities. This can have a small impact on FRTB commodity capital via the commodity basis correlation term when two records have different delivery locations.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '717a3e96-1967-5f8e-b61d-8dc6b5cfd197', 0, 'CommodityFuture', '', 'OptionUnderlyingFutureConvention', 'conventions.xsd', '/Conventions/CommodityFuture/OptionUnderlyingFutureConvention', 36, 'string', false, 'Option underlying future convention', 'Sometimes the next contract expiry, as specified in the convention, is not the correct option underlying.', 'Sometimes the next contract expiry, as specified in the convention, is not the correct option underlying. For example the base metals options expiries on the 1st Wednesday of the contract month, and during the first 3 months there are daily future contracts available. The option underlying is not the future contract which matures on the option expiry but the one which matures on the 3rd Wednesday of the month. This field is referencing to an commodity future convention which specifies the correct expiry date for the underlying contract.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e0c80b3a-d835-5c19-af47-cad97b55332f', 0, 'CommodityFuture', 'AveragingData', 'CommodityName', 'conventions.xsd', '/Conventions/CommodityFuture/AveragingData/CommodityName', 37, 'string', false, 'Commodity name', 'The name of the commodity being averaged.', 'The name of the commodity being averaged.', 'None where the convention needs it; the description says when.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6da0e5ad-668b-5393-8641-b44677c54080', 0, 'CommodityFuture', 'AveragingData', 'Period', 'conventions.xsd', '/Conventions/CommodityFuture/AveragingData/Period', 38, 'string', false, 'Period', 'This indicates the averaging period relative to the future expiry date.', 'This indicates the averaging period relative to the future expiry date. The allowable values are: \begin{itemize}', 'None where the convention needs it; the description says when.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '12a180d2-7caa-589d-b6f0-3bec3f35e85e', 0, 'CommodityFuture', 'AveragingData', 'PricingCalendar', 'conventions.xsd', '/Conventions/CommodityFuture/AveragingData/PricingCalendar', 39, 'string', false, 'Pricing calendar', 'The pricing calendar(s) used to determine the pricing dates in the averaging period.', 'The pricing calendar(s) used to determine the pricing dates in the averaging period.', 'None where the convention needs it; the description says when.', 'A calendar, such as TARGET or US-NYSE.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ca24263c-304a-5857-908d-0ea1094ab49a', 0, 'CommodityFuture', 'AveragingData', 'UseBusinessDays', 'conventions.xsd', '/Conventions/CommodityFuture/AveragingData/UseBusinessDays', 40, 'boolean', false, 'Use business days', 'A boolean flag that defaults to true if omitted.', 'A boolean flag that defaults to true if omitted. When set to true, the pricing dates in the averaging period are the set of PricingCalendar good business days. When set to false, the pricing dates in the averaging period are the complement of the set of PricingCalendar good business days. This may be useful in certain situations. For example, the contract ICE PW2 with specifications \href{https://www.theice.com/products/71090520/PJM-Western-Hub-Real-Time-Peak-2x16-Fixed-Price-Future}{here} averages the PJM Western Hub locational marginal prices over each day in the averaging period that is a Saturday, Sunday or NERC holiday. So, in this case, UseBusinessDays would be false and PricingCalendar would be US-NERC.', 'true if omitted.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7728697f-5995-5ed7-819f-5ab364ce90fb', 0, 'CommodityFuture', 'AveragingData', 'Conventions', 'conventions.xsd', '/Conventions/CommodityFuture/AveragingData/Conventions', 41, 'string', false, 'Conventions', 'The identifier for the conventions associated with the commodity being averaged.', 'The identifier for the conventions associated with the commodity being averaged.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4a581eee-98c0-5860-8c5f-1983f53fa94a', 0, 'CommodityFuture', 'AveragingData', 'DeliveryRollDays', 'conventions.xsd', '/Conventions/CommodityFuture/AveragingData/DeliveryRollDays', 42, 'integer', false, 'Delivery roll days', 'This node allows any non-negative integer value.', 'This node allows any non-negative integer value. When averaging a commodity future contract price over the averaging period, the averaging period may include an underlying future contract expiry date. This node''s value indicates when we should begin using the next future contract''s price in the averaging. If the value is zero, we should include the future contract prices up to and including the contract expiry. If the value is one, we should include the contract prices up to and including the day that is one business day before the contract expiry and then switch to using the next future contract''s price thereafter. Similarly for other non-negative integer values. If this node is omitted, it is set to zero.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f7757c83-8578-570e-8d44-a7c41412e014', 0, 'CommodityFuture', 'AveragingData', 'FutureMonthOffset', 'conventions.xsd', '/Conventions/CommodityFuture/AveragingData/FutureMonthOffset', 43, 'integer', false, 'Future month offset', 'This node allows any non-negative integer value.', 'This node allows any non-negative integer value. If this node is omitted, it is set to zero. This node indicates which future contract is being referenced on each Pricing Date in the averaging period by acting as an offset from the next available expiry date. If FutureMonthOffset is zero, the settlement price of the next available monthly contract that has not expired with respect to the Pricing Date is used as the price on that Pricing Date. If FutureMonthOffset is one, the settlement price of the second available monthly contract that has not expired with respect to the Pricing Date is used as the price on that Pricing Date. Similarly for other positive values of FutureMonthOffset.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4fc0e1af-429d-5806-ba41-d37e5070d838', 0, 'CommodityFuture', 'AveragingData', 'DailyExpiryOffset', 'conventions.xsd', '/Conventions/CommodityFuture/AveragingData/DailyExpiryOffset', 44, 'integer', false, 'Daily expiry offset', 'This node allows any non-negative integer value.', 'This node allows any non-negative integer value. It should only be used where the CommodityName being averaged has a daily contract frequency. If this node is omitted, it is set to zero. This node indicates which future contract is being referenced on each Pricing Date in the averaging period by acting as a business day offset, using the CommodityName''s expiry calendar, from the Pricing Date. It is useful in the base metals market where the future contract being averaged on each Pricing Date is the cash contract on that Pricing Date i.e.\ the contract with expiry date two business days after the Pricing Date.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5b919e81-f2b6-5a75-89ef-12be255acf83', 0, 'CrossCurrencyBasis', '', 'Id', 'conventions.xsd', '/Conventions/CrossCurrencyBasis/Id', 0, 'string', true, 'Identifier', 'The unique identifier of the convention.', 'The unique identifier of the convention. A curve segment, a quote or another convention refers to the convention by it.', 'None: the convention must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '87d2d72d-3fe5-5a68-ae12-58ca7a4b5ba7', 0, 'CrossCurrencyBasis', '', 'SettlementDays', 'conventions.xsd', '/Conventions/CrossCurrencyBasis/SettlementDays', 1, 'string', true, 'Settlement days', 'The number of business days to the start of the cross currency basis swap.', 'The number of business days to the start of the cross currency basis swap.', 'None: the convention must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '43e9786d-b701-5516-8eb7-38af29885ce1', 0, 'CrossCurrencyBasis', '', 'SettlementCalendar', 'conventions.xsd', '/Conventions/CrossCurrencyBasis/SettlementCalendar', 2, 'string', true, 'Settlement calendar', 'The business day calendar(s) for both legs and to arrive at the settlement date using the SettlementDays above.', 'The business day calendar(s) for both legs and to arrive at the settlement date using the SettlementDays above.', 'None: the convention must give it.', 'A calendar, such as TARGET or US-NYSE.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6d929897-6528-5d48-9404-74f1b9e2cc7d', 0, 'CrossCurrencyBasis', '', 'RollConvention', 'conventions.xsd', '/Conventions/CrossCurrencyBasis/RollConvention', 3, 'string', true, 'Roll convention', 'The roll convention for both legs.', 'The roll convention for both legs.', 'None: the convention must give it.', 'A business day convention, such as ModifiedFollowing or F.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '44e376f7-2824-5818-ab49-f8f51d1a0271', 0, 'CrossCurrencyBasis', '', 'FlatIndex', 'conventions.xsd', '/Conventions/CrossCurrencyBasis/FlatIndex', 4, 'string', true, 'Flat index', 'The name of the index on the leg that does not have the cross currency basis spread.', 'The name of the index on the leg that does not have the cross currency basis spread.', 'None: the convention must give it.', 'An index name, such as EUR-EURIBOR-6M.', '1.8.0.7 or earlier', null),
