        (v_dataset_id, ores_utility_system_tenant_id_fn(), '112a0a43-c8af-5688-9fab-f39b7c613122', 0, 'FX', '', 'AdvanceCalendar', 'conventions.xsd', '/Conventions/FX/AdvanceCalendar', 5, 'string', false, 'Advance calendar', 'The business day calendar(s) used for advancing dates for both spot and forwards.', 'The business day calendar(s) used for advancing dates for both spot and forwards. If not provided, it defaults to a calendar with no holidays.', 'a calendar with no holidays.', 'A calendar, such as TARGET or US-NYSE.', '1.8.0.7 or earlier', null),
