        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3ce1e268-3c20-5793-bb95-396ba2f6741d', 0, 'InflationSwap', '', 'AdjustInflationObservationDates', 'conventions.xsd', '/Conventions/InflationSwap/AdjustInflationObservationDates', 7, 'boolean', true, 'Adjust inflation observation dates', 'Flag indicating whether index observation dates should be adjusted or not.', 'Flag indicating whether index observation dates should be adjusted or not.', 'None: the convention must give it.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b51e86b0-7328-569b-b911-6208ca6e1ed5', 0, 'InflationSwap', '', 'InflationCalendar', 'conventions.xsd', '/Conventions/InflationSwap/InflationCalendar', 8, 'string', true, 'Inflation calendar', 'The calendar for the inflation leg of the swap.', 'The calendar for the inflation leg of the swap.', 'None: the convention must give it.', 'A calendar, such as TARGET or US-NYSE.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9022806e-1a27-5ac5-997d-61e488b9c693', 0, 'InflationSwap', '', 'InflationConvention', 'conventions.xsd', '/Conventions/InflationSwap/InflationConvention', 9, 'string', true, 'Inflation convention', 'The rolling convention for the inflation leg of the swap.', 'The rolling convention for the inflation leg of the swap.', 'None: the convention must give it.', 'A business day convention, such as ModifiedFollowing or F.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '004ba17e-9d3b-59b7-bd1a-2330c133da57', 0, 'InflationSwap', '', 'StartDelay', 'conventions.xsd', '/Conventions/InflationSwap/StartDelay', 10, 'integer', false, 'Start delay', '[Optional] The inflation swap starts n business days after today, defaults to zero if omitted.', '[Optional] The inflation swap starts n business days after today, defaults to zero if omitted.', 'zero if omitted.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'da9480a3-a66b-57cf-9df9-af00a7c78dca', 0, 'InflationSwap', '', 'StartDelayConvention', 'conventions.xsd', '/Conventions/InflationSwap/StartDelayConvention', 11, 'string', false, 'Start delay convention', '[Optional] BusinessDayConvention to adjust the start day, defaults to Following if omitted.', '[Optional] BusinessDayConvention to adjust the start day, defaults to Following if omitted.', 'Following if omitted.', 'A business day convention, such as ModifiedFollowing or F.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6aef8c94-27d0-5396-aa93-2619b49dd930', 0, 'InflationSwap', '', 'PublicationRoll', 'conventions.xsd', '/Conventions/InflationSwap/PublicationRoll', 12, 'string', false, 'Publication roll', 'This is an optional node taking the values None, OnPublicationDate or AfterPublicationDate.', 'This is an optional node taking the values None, OnPublicationDate or AfterPublicationDate. If omitted, the value None is used. Currently, our only known use case for a value other than None is for Australian zero coupon inflation indexed swaps (ZCIIS). Here, the index is published quarterly on the last Wednesday of the month following the end of the reference quarter. The start date and maturity date of the market quoted ZCIIS roll to the next quarterly date after the publication date of the index. For example, the AU CPI value for Q3 2020, i.e.\ 1 Jul 2020 to 30 Sep 2020 was released on 28 Oct 2020. On 27 Oct 2020, before the index publication date, the market 5Y ZCIIS would start on 15 Sep 2020 and end on 15 Sep 2025 and reference the Q2 inflation index value. On 29 Oct 2020, after the index publication date, the market 5Y ZCIIS would start on 15 Dec 2020 and end on 15 Dec 2025 and reference the Q3 inflation index value. On the release date, i.e. 28 Oct 2020, the market ZCIIS that is set up is determined by whether the PublicationRoll value is OnPublicationDate or AfterPublicationDate. If it is set to OnPublicationDate, the swap rolls on this date and hence the market 5Y ZCIIS would start on 15 Dec 2020 and end on 15 Dec 2025 and reference the Q3 inflation index value. If it is set to AfterPublicationDate, the swap does not roll on the publication date and instead rolls on the next day, and hence the market 5Y ZCIIS would start on 15 Sep 2020 and end on 15 Sep 2025 and reference the Q2 inflation index value. The publication schedule for the index must be provided in the PublicationSchedule node if PublicationRoll is not None. An example of the AU CPI conventions set up is given in Listing the guide.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2c106949-1589-5fcb-be4c-c35fabecfd92', 0, 'IntradayPowerLoad', '', 'Id', 'conventions.xsd', '/Conventions/IntradayPowerLoad/Id', 0, 'string', true, 'Identifier', 'The unique identifier of the convention.', 'The unique identifier of the convention. A curve segment, a quote or another convention refers to the convention by it.', 'None: the convention must give it.', 'Text.', '1.8.0.7 or earlier', null),
