        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0468a1e4-0b71-55d8-8393-1092540c856a', 0, 'BondFutureVolatilities', 'BondFutureVolatility', 'DayCounter', 'curveconfig.xsd', '/CurveConfiguration/BondFutureVolatilities/BondFutureVolatility/DayCounter', 3, 'string', false, 'Day counter', 'The day count basis used internally by the curve to calculate the time between dates.', 'The day count basis used internally by the curve to calculate the time between dates. If omitted it defaults to A365.', 'A365.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '79374cc4-2881-52ad-81c8-7fde5d0c1400', 0, 'BondFutureVolatilities', 'BondFutureVolatility', 'Calendar', 'curveconfig.xsd', '/CurveConfiguration/BondFutureVolatilities/BondFutureVolatility/Calendar', 4, 'string', false, 'Calendar', 'Only applicable to overnight index futures with date generation rule `FirstDayOfMonth''.', 'Only applicable to overnight index futures with date generation rule `FirstDayOfMonth''. Overwrites the calendar used to adjust the start and end date of the future. Optional, if not given, the overnight index publishing calendar will be used to adjust the future start and end date.', 'NullCalendar.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8cb9ae38-25d9-55a9-9d05-d66a1a2ac64b', 0, 'BondFutureVolatilities', 'BondFutureVolatility', 'YieldCurveId', 'curveconfig.xsd', '/CurveConfiguration/BondFutureVolatilities/BondFutureVolatility/YieldCurveId', 5, 'string', false, 'Yield curve id', 'The ID of a yield curve in the currency of the bond future contract of the form Yield/CCY/NAME.', 'The ID of a yield curve in the currency of the bond future contract of the form Yield/CCY/NAME.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b7aa4668-6c26-544f-a1aa-b1d4d7c9cc35', 0, 'BondFutureVolatilities', 'BondFutureVolatility', 'UseOnlyPutCall', 'curveconfig.xsd', '/CurveConfiguration/BondFutureVolatilities/BondFutureVolatility/UseOnlyPutCall', 6, 'string', false, 'Use only put call', 'If supplied, it must be either C to use only calls or P to use only puts.', 'If supplied, it must be either C to use only calls or P to use only puts. The market data may contain quotes of the form BOND_FUTURE_OPTION/RATE_LNVOL/TYM26/2026-04-02/121.25/C and BOND_FUTURE_OPTION/RATE_LNVOL/TYM26/2026-04-02/121.25/P i.e. call and put volatilities for the same bond future contract with the same expiry and strike. Setting this flag to C ignores all put quotes and setting it to P ignores all call quotes. Note the comment in the CurveId bullet point above when this flag is set. If omitted, it is empty and both call and put volatilities are used to construct the surface if they are in the market data and match the configuration. The volatility that is chosen if both a call and a put volatility is found for a particular grid point is determined by the setting of the PreferOutOfTheMoney field described below.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '74b64e02-3ae2-5585-89a0-375683f4be3f', 0, 'BondFutureVolatilities', 'BondFutureVolatility', 'StrikeFactor', 'curveconfig.xsd', '/CurveConfiguration/BondFutureVolatilities/BondFutureVolatility/StrikeFactor', 7, 'double', false, 'Strike factor', 'A real number used to divide the strikes found in the quote strings such that the strike is in absolute terms.', 'A real number used to divide the strikes found in the quote strings such that the strike is in absolute terms. For example, if a quote string of BOND_FUTURE_OPTION/RATE_LNVOL/TYM26/2026-04-02/121.25/C is found in the market data and the StrikeFactor is 100, the strike of 121.25 is divided by 100 so that 1.2125 is used internally in ORE. The same configuration is achieved if the quote is of the form', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f14ff0f3-3c22-5372-a31a-9ce6edb0ee6c', 0, 'BondFutureVolatilities', 'BondFutureVolatility', 'OneDimSolverConfig', 'curveconfig.xsd', '/CurveConfiguration/BondFutureVolatilities/BondFutureVolatility/OneDimSolverConfig', 8, 'string', false, 'One dim solver config', 'This provides the options for the root search in the stripping of the volatilities from premia.', 'This provides the options for the root search in the stripping of the volatilities from premia. If omitted, the default set of options shown in Listing is used. The MinMax node can be replaced with a single Step node that accepts a double giving the step size to use in the root search.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fc924f35-2486-5f59-99f5-9dba82bffa21', 0, 'BondFutureVolatilities', 'BondFutureVolatility', 'PreferOutOfTheMoney', 'curveconfig.xsd', '/CurveConfiguration/BondFutureVolatilities/BondFutureVolatility/PreferOutOfTheMoney', 9, 'boolean', false, 'Prefer out of the money', 'If a put and a call quote with the same tenor and expiry are found in the market data and match the configuration, this flag determines which quote is used.', 'If a put and a call quote with the same tenor and expiry are found in the market data and match the configuration, this flag determines which quote is used. If set to true, out of the money call and put quotes are used. If set to false, in the money call and put quotes are used. If omitted, the default value is true.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eb0fb438-373a-5094-a30c-c46dca78b42a', 0, 'BondFutureVolatilities', 'BondFutureVolatility', 'TreatAsEuropean', 'curveconfig.xsd', '/CurveConfiguration/BondFutureVolatilities/BondFutureVolatility/TreatAsEuropean', 10, 'boolean', false, 'Treat as european', 'If the ExerciseType is American and this is set to true, the stripping process ignores the American exercise and uses a Black-76 European engine to strip the volatilities from the premia.', 'If the ExerciseType is American and this is set to true, the stripping process ignores the American exercise and uses a Black-76 European engine to strip the volatilities from the premia. If omitted, the default value is false.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '02b00d1a-81a2-5121-9ebb-eb8f342d930b', 0, 'CDSVolatilities', 'CDSVolatility', 'Expiries', 'curveconfig.xsd', '/CurveConfiguration/CDSVolatilities/CDSVolatility/Expiries', 2, 'string', true, 'Expiries', 'comma separated list of expiry tenors and or expiry dates.', 'comma separated list of expiry tenors and or expiry dates. A single wildcard character, *, can be used here also to indicate that all expiries found in the market data for this CDS volatility configuration should be used when building the CDS volatility surface.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fd7e3468-3f8d-5d94-a402-5ebc2b60205e', 0, 'CDSVolatilities', 'CDSVolatility', 'QuoteName', 'curveconfig.xsd', '/CurveConfiguration/CDSVolatilities/CDSVolatility/QuoteName', 4, 'string', false, 'Quote name', 'this node is optional and the allowable value is any string.', 'this node is optional and the allowable value is any string. This value can be used in determining the name and term that appears in the quote strings that are searched for in the market data to feed into the CDS volatility surface construction. How it is used has been outlined above when describing the deprecated CDS volatility curve configuration.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c32af73b-0718-5742-ad1e-0f3b0a847e98', 0, 'CDSVolatilities', 'CDSVolatility', 'DayCounter', 'curveconfig.xsd', '/CurveConfiguration/CDSVolatilities/CDSVolatility/DayCounter', 5, 'string', false, 'Day counter', 'allowable value is any valid day count fraction.', 'allowable value is any valid day count fraction. As stated above, this node is optional and defaults to A365F.', 'A365F.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ea986dcf-0b45-5099-90a2-7e63741c52be', 0, 'CDSVolatilities', 'CDSVolatility', 'Calendar', 'curveconfig.xsd', '/CurveConfiguration/CDSVolatilities/CDSVolatility/Calendar', 6, 'string', false, 'Calendar', 'allowable value is any valid calendar.', 'allowable value is any valid calendar. As stated above, this node is optional and defaults to NullCalendar.', 'NullCalendar.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fb8ced4f-d25c-571a-af94-312dd32e8f2f', 0, 'CDSVolatilities', 'CDSVolatility', 'StrikeType', 'curveconfig.xsd', '/CurveConfiguration/CDSVolatilities/CDSVolatility/StrikeType', 7, 'string', false, 'Strike type', 'allowable value is either Price or Spread.', 'allowable value is either Price or Spread. This flag denotes if the strikes are in terms of spread or price. Currently, this is merely informational and as outlined in the Strikes section above, it is the responsibility of the user to ensure that the strike type in trades aligns with the configured strike type in the CDS volatility surfaces.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5a0b5f79-262b-5946-aacf-2a6f253d084f', 0, 'CDSVolatilities', 'CDSVolatility', 'StrikeFactor', 'curveconfig.xsd', '/CurveConfiguration/CDSVolatilities/CDSVolatility/StrikeFactor', 8, 'double', false, 'Strike factor', 'this node is optional and the allowable value is any positive real number.', 'this node is optional and the allowable value is any positive real number. It defaults to 1. The strikes configured and found in the market data quote strings may not be in absolute terms. For example, a quote string such as INDEX_CDS_OPTION/RATE_LNVOL/CDXIGS33V1/5Y/1M/115 could be given to indicate an index CDS option volatility quote for CDX IG Series 33 Version 1, with underlying index term 5Y expiring in 1M with a strike spread of 115 bps. The strike here is in bps and needs to be divided by 10,000 before being used in the ORE volatility objects. The StrikeFactor would be set to 10000 here.', '1.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a7bb27ba-c8eb-5a46-8517-5bf8fa6b821d', 0, 'CDSVolatilities', 'CDSVolatility', 'PriceInfo', 'curveconfig.xsd', '/CurveConfiguration/CDSVolatilities/CDSVolatility/PriceInfo', 9, 'string', false, 'Price info', 'this node is optional and only relevant when QuoteType is set to Premium.', 'this node is optional and only relevant when QuoteType is set to Premium. It is discussed further below.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b9dede91-b244-5392-8e04-b080ac2f932b', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'CurveId', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/CurveId', 0, 'string', true, 'Curve id', 'Unique identifier for the cap floor volatility structure.', 'Unique identifier for the cap floor volatility structure.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'af7484d4-9f26-51ae-96b6-b4bc17008d3f', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'CurveDescription', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/CurveDescription', 1, 'string', true, 'Curve description', 'A description of the volatility structure.', 'A description of the volatility structure. It is for information only and may be left blank.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eed9663a-3a5d-555b-af15-a88ab551e967', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'VolatilityType', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/VolatilityType', 2, 'string', true, 'Volatility type', 'Indicates the cap floor volatility type.', 'Indicates the cap floor volatility type. It may be Normal, Lognormal or ShiftedLognormal. Note that this then determines which market data points are looked up in the market when creating the ATM cap floor curve and how they are interpreted when stripping the optionlets. In particular, the market will be searched for market data points of the form CAPFLOOR/RATE_NVOL/Currency/Tenor/IndexTenor/1/1/0, CAPFLOOR/RATE_LNVOL/Currency/Tenor/IndexTenor/1/1/0 or CAPFLOOR/RATE_SLNVOL/Currency/Tenor/IndexTenor/1/1/0 respectively.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b3fd1551-e197-57a9-baed-a121577d2f23', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'Extrapolation', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/Extrapolation', 3, 'string', true, 'Extrapolation', 'Indicates the extrapolation in the time direction before the first optionlet volatility and after the last optionlet volatility.', 'Indicates the extrapolation in the time direction before the first optionlet volatility and after the last optionlet volatility. The extrapolation occurs on the stripped optionlet volatilities. The allowable values are None, Flat and Linear. If set to None, extrapolation is turned off and an exception is thrown if the optionlet surface is queried outside the allowable times. If set to Flat, the first optionlet volatility is used before the first time and the last optionlet volatility is used after the last time. If set to Linear, the interpolation method configured in InterpolationMethod is used to extrapolate.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3b3eac29-9e18-5b1a-b22d-f9eee6bd3774', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'IncludeAtm', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/IncludeAtm', 4, 'boolean', true, 'Include atm', 'A boolean value indicating if an ATM curve should be used.', 'A boolean value indicating if an ATM curve should be used. Allowable boolean values are given in the the guide. As we are describing an ATM curve here, this node should be set to true as shown in .', 'None: the curve must give it.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2068c1c8-0361-5123-a5cc-3dc166133646', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'Calendar', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/Calendar', 5, 'string', true, 'Calendar', 'The calendar used to advance dates by periods in the underlying structure.', 'The calendar used to advance dates by periods in the underlying structure. In particular, it is used in deriving the cap maturity dates from the configured cap tenors. Allowable values are given in the the guide.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0c9243e4-a591-5835-9618-5c3208f00569', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'DayCounter', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/DayCounter', 6, 'string', true, 'Day counter', 'The day counter used to convert from dates to times in the underlying structure.', 'The day counter used to convert from dates to times in the underlying structure. Allowable values are given in the the guide.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '17e10660-278b-53c2-8e0f-93f102e66c64', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'BusinessDayConvention', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/BusinessDayConvention', 7, 'string', true, 'Business day convention', 'The business day convention used to advance dates by periods in the underlying structure.', 'The business day convention used to advance dates by periods in the underlying structure. In particular, it is used in deriving the cap maturity dates from the configured cap tenors. Allowable values are given in the Table under Roll Convention.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ffd3753b-9d2a-5b7c-968e-44d492eeff03', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'DiscountCurve', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/DiscountCurve', 8, 'string', true, 'Discount curve', 'A reference to a valid discount curve specification that will be used to discount cashflows during the stripping process.', 'A reference to a valid discount curve specification that will be used to discount cashflows during the stripping process. It should be of the form Yield/Currency/curve_name where curve_name is the name of a yield curve defined in the yield curve configurations.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '78cfe0f4-c762-52c2-9b8a-d483f4135483', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'QuoteIncludesIndexName', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/QuoteIncludesIndexName', 9, 'boolean', false, 'Quote includes index name', 'If true, the quote labels that are looked up in the market data to build the surface include the index name as e.g.', 'If true, the quote labels that are looked up in the market data to build the surface include the index name as e.g. in CAPFLOOR/RATE_NVOL/USD/USD-LIBOR-3M/1Y/3M/0/0/0.01. If false, the index name is not include as in CAPFLOOR/RATE_NVOL/USD/1Y/3M/0/0/0.01. If the flag is not given, it defaults to false. Including the index name in the market quotes allows to build cap surfaces on different underlying indices with the same tenor. The flag also affects shift quotes as e.g. CAPFLOOR/SHIFT/USD/USD-LIBOR-3M/5Y (index included in quote) vs. CAPFLOOR/SHIFT/USD/5Y (index not included in quote).', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3e65c635-055c-5fcf-9a09-b57818038caa', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'Tenors', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/Tenors', 10, 'string', false, 'Tenors', 'A comma separated list of valid tenor strings giving the cap floor maturity tenors to be used in the ATM curve.', 'A comma separated list of valid tenor strings giving the cap floor maturity tenors to be used in the ATM curve. If omitted, the tenors for the ATM curve must be provided in the AtmTenors node instead. If the tenors are provided here, the AtmTenors node may be omitted.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7e6c9316-f043-5749-a403-ab2a2622a88c', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'OptionalQuotes', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/OptionalQuotes', 12, 'boolean', false, 'Optional quotes', 'A boolean flag to indicate whether market data quotes for all tenors are required.', 'A boolean flag to indicate whether market data quotes for all tenors are required. If true, we attempt to build the curve from whatever quotes are provided. If false, the curve will fail to build if any quotes are missing. This also applies to quotes for the AtmTenors. Default value is false.', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b7c0d8f8-1cc8-558a-8ae1-b8ad71bdb551', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'AtmTenors', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/AtmTenors', 13, 'string', false, 'Atm tenors', 'A comma separated list of valid tenor strings giving the cap floor maturities to be used in the ATM curve.', 'A comma separated list of valid tenor strings giving the cap floor maturities to be used in the ATM curve. If omitted, the tenors for the ATM curve must be provided in the Tenors node instead. If the tenors are provided here, the Tenors node may be omitted.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '81df6f7e-1681-5118-9bc4-0dbc341920a4', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'FlatFirstPeriod', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/FlatFirstPeriod', 14, 'boolean', false, 'Flat first period', 'If true (default) the volatilities of the caplets that form the first par market cap are set to the same value.', 'If true (default) the volatilities of the caplets that form the first par market cap are set to the same value. If false and a global bootstrap is used, the caplet volatility at t=0 is included in the opimization and the caplet volatilities of the first par market cap are interpolated between the value at t=0 and the next interpolation node. Since the node at t=0 adds a degree of freedom, the parameter SmoothnessLambda should be set to a positive value in the bootstrap config. See sec:bootstrap_config.', 'true.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '412a196d-a4bc-5a18-baf4-173bfde1d779', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'UseEffectiveVolatility', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/UseEffectiveVolatility', 15, 'boolean', false, 'Use effective volatility', 'Only applies to overnight caplets.', 'Only applies to overnight caplets. If false (default), volatilities in the surface will be ``stripped volatilities'''', i.e. they will be placed on the first fixing date of the caplet and a decay adjustment will be applied when pricing the caplet. If true, volatilities in the surface will be ``effective volatliities'''', i.e. they will be placed on the last fixing date of the caplet and the market black formula will be used to price such a caplet, using the last fixing date to calculate the usual black variance, without decay adjustment.', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7b26a142-8bec-5539-a38a-f554040ac99e', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'OutputVolatilityType', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/OutputVolatilityType', 16, 'string', false, 'Output volatility type', 'Specifies the vol used for caplet bootstrap and result surface, one of Normal, Lognormal or ShiftedLognormal, defaults to \ Normal for backwards compatibility before release 1.83.0', 'Specifies the vol used for caplet bootstrap and result surface, one of Normal, Lognormal or ShiftedLognormal, defaults to \ Normal for backwards compatibility before release 1.83.0', '\ Normal for backwards compatibility before release 1.83.0.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8771bf11-00eb-58a7-b9ee-438d00f285ce', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'ModelShift', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/ModelShift', 17, 'double', false, 'Model shift', 'Specifies the vol shift used for SABR model (if applicable).', 'Specifies the vol shift used for SABR model (if applicable). Defaults to input market data shift.', 'input market data shift.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '91d7c2c6-f2df-5686-a0e1-840e9265a6f8', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'OutputShift', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/OutputShift', 18, 'double', false, 'Output shift', 'Specifies the vol shift used for caplet bootstrap and result surface (if OutputVolatilityType is Lognormal or ShiftedLognormal), defaults to input market data shift.', 'Specifies the vol shift used for caplet bootstrap and result surface (if OutputVolatilityType is Lognormal or ShiftedLognormal), defaults to input market data shift.', 'input market data shift.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'eb9e7c11-867d-5d8e-8857-b866b132cb41', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'Index', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/Index', 20, 'string', false, 'Index', 'A valid interest rate index name giving the index underlying the cap floor quotes.', 'A valid interest rate index name giving the index underlying the cap floor quotes. This has to be an ibor, term or overnight index. Allowable values are given in the the guide.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dbe928f3-0156-5676-83f2-87f7bb89f78c', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'RateComputationPeriod', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/RateComputationPeriod', 21, 'string', false, 'Rate computation period', 'For overnight indices, the caplet compounding period, e.g.', 'For overnight indices, the caplet compounding period, e.g. 3M for USD-SOFR. Not relevant for ibor, term indices.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6a7621ba-16fa-5972-9289-9d8e09327884', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'SettlementDays', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/SettlementDays', 23, 'integer', false, 'Settlement days', 'Any non-negative integer is allowed here.', 'Any non-negative integer is allowed here. If omitted, it is assumed to be 0. If provided the reference date of the term volatility curve and the stripped optionlet volatility structure will be calculated by advancing the valuation date by this number of days using the configured calendar and business day convention. In general, this should be omitted or set to 0.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '790fda34-fea5-545d-8b87-d736c55606b8', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'InterpolateOn', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/InterpolateOn', 24, 'string', false, 'Interpolate on', 'As referenced above, the allowable values are TermVolatilities or OptionletVolatilities.', 'As referenced above, the allowable values are TermVolatilities or OptionletVolatilities. As we are describing here an ATM curve with interpolation on term volatilities, this should be set to TermVolatilities as shown in the guide.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5a39f7e2-8cb0-55a9-b145-e35aee1dd0bf', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'TimeInterpolation', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/TimeInterpolation', 25, 'string', false, 'Time interpolation', 'Indicates the interpolation and extrapolation, if allowed by the Extrapolation node, in the time direction.', 'Indicates the interpolation and extrapolation, if allowed by the Extrapolation node, in the time direction. As InterpolateOn is set to OptionletVolatilities here, the interpolation is used to interpolate the optionlet volatilities only i.e.\ there is no interpolation on the term cap floor volatility curve. The allowable values are Linear, LinearFlat, BackwardFlat, Cubic and CubicFlat. If not set, LinearFlat is assumed. Note that Linear indicates linear interpolation and linear extrapolation. LinearFlat indicates linear interpolation and flat extrapolation. Analogous meanings apply for Cubic and CubicFlat.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c4b6b561-62fd-520e-a755-f7330e10da6c', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'StrikeInterpolation', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/StrikeInterpolation', 26, 'string', false, 'Strike interpolation', 'Indicates the interpolation and extrapolation, if allowed by the Extrapolation node, in the strike direction.', 'Indicates the interpolation and extrapolation, if allowed by the Extrapolation node, in the strike direction. Again, as InterpolateOn is set to OptionletVolatilities here, the interpolation is used to interpolate the optionlet volatilities in the strike direction. The allowable values are Linear, LinearFlat, Cubic and CubicFlat or one of the SABR variants Hagan2002Lognormal, Hagan2002Normal, Hagan2002NormalZeroBeta, Antonov2015FreeBoundaryNormal, KienitzLawsonSwaynePde, FlochKennedy. The SABR variants are only supported for InterpolateOn = OptionVolatilities (or if InputType = OptionletVolatilities). If not set, LinearFlat is assumed.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3804ab1b-49bd-5839-abcc-203d37e079f8', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'InterpolationMethod', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/InterpolationMethod', 27, 'string', false, 'Interpolation method', 'Indicates the interpolation in the time direction.', 'Indicates the interpolation in the time direction. As InterpolateOn is set to TermVolatilities here, the interpolation is used in the stripping process to interpolate the term cap floor volatility curve as explained above. It is also used to interpolate the optionlet volatilities when an optionlet volatility is queried from the stripped optionlet structure. The allowable values are Bilinear and BicubicSpline. If not set, BicubicSpline is assumed. Obviously, as we are describing an ATM curve here, there is no interpolation in the strike direction so when Bilinear is set the time interpolation is linear and when BicubicSpline is set the time interpolation is cubic spline.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '926718d6-fba2-5ca7-b6ad-d1218081bc28', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'BootstrapConfig', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/BootstrapConfig', 28, 'string', false, 'Bootstrap config', 'This node holds configuration details for the iterative bootstrap that are described in section .', 'This node holds configuration details for the iterative bootstrap that are described in section . If omitted, this node''s default values described in section are used.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6f0a4dc9-9caf-5598-98c2-bda5cfd5d4ae', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'ParametricSmileConfiguration', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/ParametricSmileConfiguration', 29, 'string', false, 'Parametric smile configuration', 'Optional.', 'Optional. Applies to SABR only. If not given, default values are used. Allows to specify initial values for calibrated parameters, to exclude single parameters from calibration and to set calibration parameters. See listing . See Example 59 for how to configure single value and termstructures of sabr parameters for swaption and cap curve configs.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5bbb0179-a617-541e-9660-ac6e856fb1de', 0, 'CapFloorVolatilities', 'CapFloorVolatility', 'InputType', 'curveconfig.xsd', '/CurveConfiguration/CapFloorVolatilities/CapFloorVolatility/InputType', 30, 'string', false, 'Input type', 'The type of the marketdata input.', 'The type of the marketdata input. Allowable values are TermVolatilities or OptionletVolatilities. As we are describing term cap volatilities input, this should be set to TermVolatilities or omitted as shown in the guide. If omitted, the default value is TermVolatilities.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '28ca592b-d9cf-5358-ba63-ef3baf2bb646', 0, 'CommodityCurves', 'CommodityCurve', 'CurveId', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/CurveId', 0, 'string', true, 'Curve id', 'Unique identifier for the curve.', 'Unique identifier for the curve.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'be109d1d-a937-5c11-9f30-98f470471e75', 0, 'CommodityCurves', 'CommodityCurve', 'CurveDescription', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/CurveDescription', 1, 'string', true, 'Curve description', 'A description of the curve.', 'A description of the curve. This field may be left blank.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd0a4d8ea-ce6b-5e09-bb28-539c8e3af589', 0, 'CommodityCurves', 'CommodityCurve', 'Currency', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/Currency', 2, 'string', true, 'Currency', 'The commodity curve currency.', 'The commodity curve currency.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '83346419-3a34-5ff6-afeb-cde3a7498ede', 0, 'CommodityCurves', 'CommodityCurve', 'DayCounter', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/DayCounter', 5, 'string', false, 'Day counter', 'The day count basis used internally by the curve to calculate the time between dates.', 'The day count basis used internally by the curve to calculate the time between dates.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fa7df9f0-b1b7-5674-a3a1-d5b67d7c2d6d', 0, 'CommodityCurves', 'CommodityCurve', 'InterpolationMethod', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/InterpolationMethod', 6, 'string', false, 'Interpolation method', 'The variable on which the interpolation is performed.', 'The variable on which the interpolation is performed. The allowable values are Linear, LogLinear, Cubic, Hermite, LinearFlat, LogLinearFlat, CubicFlat, HermiteFlat, BackwardFlat, ForwardFlat. This is different to yield curves above in that Flat versions of the standard methods are defined, with each of these if there is no Spot price than any extrapolation between T_0 and the first future price will be flat (i.e. the first future price will be copied back ``Flat'''' to T_0). If the element is omitted or left blank, then it defaults to Linear.', 'Linear.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '08a071d3-2c25-5056-b3ac-6577e40a2341', 0, 'CommodityCurves', 'CommodityCurve', 'SpotQuote', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/SpotQuote', 7, 'string', false, 'Spot quote', 'The spot price quote, if omitted then the spot value will be interpolated.', 'The spot price quote, if omitted then the spot value will be interpolated.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b7861c06-0a7d-5534-8c64-a66a7247057f', 0, 'CommodityCurves', 'CommodityCurve', 'Quotes', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/Quotes', 8, 'string', false, 'Quotes', 'forward price quotes.', 'forward price quotes. These can be a futures price or forward points.', 'Quote.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fb7748eb-4099-5e3c-808c-68109fdfab75', 0, 'CommodityCurves', 'CommodityCurve', 'Conventions', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/Conventions', 9, 'string', false, 'Conventions', 'The conventions to use, if omited it is assumed that these quotes are Outright prices.', 'The conventions to use, if omited it is assumed that these quotes are Outright prices.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '00dc3827-b376-5aa5-933c-05a2487a54d7', 0, 'CommodityCurves', 'CommodityCurve', 'Extrapolation', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/Extrapolation', 10, 'boolean', false, 'Extrapolation', 'Set to True or False to enable or disable extrapolation respectively.', 'Set to True or False to enable or disable extrapolation respectively. If the element is omitted or left blank, then it defaults to True.', 'True.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'aeba4c9a-146f-53c4-9145-b5df0ccd2a5c', 0, 'CommodityCurves', 'CommodityCurve', 'BasePriceCurve', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BasePriceCurve', 12, 'string', false, 'Base price curve', 'The identifier for the base future commodity price curve.', 'The identifier for the base future commodity price curve.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dda87442-c267-511d-90ea-75a0e32325bf', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'Accuracy', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/Accuracy', 14, 'double', false, 'Accuracy', 'The accuracy with which the implied quote must match the market quote for each instrument in the curve bootstrap (iterative bootstrap) or the accuracy of the global optimizer (global bootstrap).', 'The accuracy with which the implied quote must match the market quote for each instrument in the curve bootstrap (iterative bootstrap) or the accuracy of the global optimizer (global bootstrap). This node should hold a positive real number. If omitted, the default value is 1.0e-12.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c8fda864-56bf-5abb-a995-712274ecad03', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'GlobalAccuracy', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/GlobalAccuracy', 15, 'double', false, 'Global accuracy', 'If the interpolation method in the bootstrap is global, e.g.', 'If the interpolation method in the bootstrap is global, e.g. cubic spline, the bootstrap routine needs to perform multiple iterative bootstraps of the curve to converge. After each such bootstrap of the full curve, the absolute value of the change between the current bootstrap and previous bootstrap for the curve value at each pillar is calculated. The global bootstrap is deemed to have converged if the maximum of these changes is less than the global accuracy or the accuracy from the Accuracy node. This node should hold a positive real number. If omitted, the global accuracy is set equal to the accuracy from the Accuracy node. This node is useful in some cases where a slightly less restrictive accuracy, than that given by the Accuracy node, is needed for the global bootstrap.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a761f411-0f84-5cf3-a8c8-825fd921b4a4', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'DontThrow', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/DontThrow', 16, 'boolean', false, 'Dont throw', 'If this node is set to true, the curve bootstrap does not throw an error when the bootstrap fails at a pillar.', 'If this node is set to true, the curve bootstrap does not throw an error when the bootstrap fails at a pillar. Instead, a curve value is sought at the failing pillar that minimises the absolute value of the difference between the implied quote and the market quote at that pillar. The minimum is sought between the minimum and maximum curve value that was used in the root finding routine that failed at the pillar. The number of steps used in this search is given by the DontThrowSteps node below. This node should hold a boolean value. If omitted, the default value is false i.e. the bootstrap throws an exception at the first pillar where the bootstrap fails.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e2350674-ad7a-5b73-a721-ed98b3e91c12', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'MaxAttempts', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/MaxAttempts', 17, 'integer', false, 'Max attempts', 'At each pillar, the bootstrap routine searches between a minimum curve value and a maximum curve value for a curve value that gives an implied quote that matches the market quote at that pillar.', 'At each pillar, the bootstrap routine searches between a minimum curve value and a maximum curve value for a curve value that gives an implied quote that matches the market quote at that pillar. In some cases, the minimum curve value and maximum curve value are too restrictive and the bootstrap fails at a pillar. This node determines how many times the bootstrap should be attempted at each pillar. For example, if the node is set to 1, the bootstrap uses the minimum curve value and maximum curve value implied in the code and fails if a root is not found. If this node is set to 2 and the first attempt fails, the minimum curve value is reduced by a factor specified in the node MinFactor, the maximum curve value is increased by a factor specified in the node MaxFactor and a second attempt is made to find a root between the enlarged bounds. If no root is found, the bootstrap then fails at this pillar. This node should hold a positive integer. If omitted, the default value is 5.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c0ee3917-6041-56fb-94cc-f4be22fd43c5', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'MaxFactor', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/MaxFactor', 18, 'double', false, 'Max factor', 'This node is used only if MaxAttempts is greater than 1.', 'This node is used only if MaxAttempts is greater than 1. The meaning of this node is given in the description of the MaxAttempts node. This node should hold a positive real number. If omitted, the default value is 2.0.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4fecbc35-f319-5e60-94cc-65c927f03f85', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'MinFactor', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/MinFactor', 19, 'double', false, 'Min factor', 'This node is used only if MaxAttempts is greater than 1.', 'This node is used only if MaxAttempts is greater than 1. The meaning of this node is given in the description of the MaxAttempts node. This node should hold a positive real number. If omitted, the default value is 2.0.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ff42896f-6cc2-5393-b04b-93b4692b6a26', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'DontThrowSteps', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/DontThrowSteps', 20, 'integer', false, 'Dont throw steps', 'This node is used only if DontThrow is true.', 'This node is used only if DontThrow is true. The meaning of this node is given in the description of the DontThrow node. This node should hold a positive integer. If omitted, the default value is 10.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0995b162-f17b-5ad8-80b7-b9af63f2d572', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'Global', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/Global', 21, 'boolean', false, 'Global', 'Defaults to false.', 'Defaults to false. This nodes specifies whether the curve should use a global bootstrap over all instruments of the curve (true) or iterative bootstrap (false, default value). If global bootstrap is used, only the fields Accuracy and SmoothnessLambda of the BootstrapConfig are relevant. Accurcy specifies the accuracy of the global optimizer in this case. Global bootstrap is required to build curves that form a cycle in the dependency graph, in this case all members of the cycle must have Global set to true in their bootstrap configs. In this case a global optimization is run over all instrument of all members of the cycle simultaneously. Global bootstrap is also required if according to the PillarChoice configuration of each segment there are curve instrument without or with more than one associated curve pillar date. Finally, global bootstrap can be preferable over iterative bootstrap if the latter requires an outer convergence loop, i.e. if a pillar choice is not set to LastRelevatDate or if the interpolation is non-local.', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cb8923a8-905b-5ab1-aec1-ef25c46f8262', 0, 'CommodityCurves', 'CommodityCurve/BootstrapConfig', 'SmoothnessLambda', 'curveconfig.xsd', '/CurveConfiguration/CommodityCurves/CommodityCurve/BootstrapConfig/SmoothnessLambda', 22, 'double', false, 'Smoothness lambda', 'Defaults to zero.', 'Defaults to zero. Only applies if GLobal is set to true. If positive, penalty components are included in the global optimization used to build a curve. For each adjacent pair of discrete forward rates F_i, F_i+1 between curve interpolation pillars, the term (F_i+1 - F_i) is added to the target function vector of which the MSE is optimized.', 'zero.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5187898d-77bf-508a-ba73-0a415b5ff865', 0, 'CommodityVolatilities', 'CommodityVolatility', 'CurveId', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/CurveId', 0, 'string', true, 'Curve id', 'Unique identifier for the curve.', 'Unique identifier for the curve.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3bd3dcc5-511d-5f8a-b0dc-b62610dca859', 0, 'CommodityVolatilities', 'CommodityVolatility', 'CurveDescription', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/CurveDescription', 1, 'string', true, 'Curve description', 'A description of the curve.', 'A description of the curve. This field may be left blank.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f4186536-9158-5209-ad6b-1bd0b51a5548', 0, 'CommodityVolatilities', 'CommodityVolatility', 'Currency', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/Currency', 2, 'string', true, 'Currency', 'The commodity curve currency.', 'The commodity curve currency.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bd10de24-fcdd-52be-8a83-6db464eb32fc', 0, 'CommodityVolatilities', 'CommodityVolatility', 'FutureConventions', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/FutureConventions', 3, 'string', false, 'Future conventions', 'Depending on the quotes that are provided in the Quotes section, a CommodityFuture convention may be needed in order to derive an option expiry date from the Expiry portion of the commodity option quote.', 'Depending on the quotes that are provided in the Quotes section, a CommodityFuture convention may be needed in order to derive an option expiry date from the Expiry portion of the commodity option quote. In particular, as outlined in Section , the Expiry portion of a commodity option quote allows for continuation expiries of the form cN. The N is a positive integer meaning the N-th next expiry after the valuation date on which we are building the commodity volatility curve. When a continuation expiry is used in a quote, the FutureConventions is needed and gives the ID of the conventions associated with the commodity for which we are trying to build the volatility curve. These conventions are used to determine the explicit expiry date for the given option quote from the continuation expiry.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '06980bfc-ec7a-5c94-a40c-743c215dd09e', 0, 'CommodityVolatilities', 'CommodityVolatility', 'PriceCurveId', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/PriceCurveId', 4, 'string', false, 'Price curve id', 'The ID of a price curve for the commodity of the form Commodity/CCY/NAME.', 'The ID of a price curve for the commodity of the form Commodity/CCY/NAME. This is needed if the QuoteType is Premium. It is also needed when the QuoteType is ImpliedVolatility if either Strikes or Expiries use the single wildcard value * and both call and put quotes are found in the market for the same expiry and strike pair. In this case, it is needed to determine which quotes to use based on the value of the PreferOutOfTheMoney node.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '35744dd3-4a4e-5dbd-906c-a8e1c337bea8', 0, 'CommodityVolatilities', 'CommodityVolatility', 'YieldCurveId', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/YieldCurveId', 5, 'string', false, 'Yield curve id', 'The ID of a yield curve in the currency of the commodity of the form Yield/CCY/NAME.', 'The ID of a yield curve in the currency of the commodity of the form Yield/CCY/NAME. This is needed if the QuoteType is Premium in the stripping of the volatilities from premia.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f81dbe77-8ba0-5e77-b8de-111f23ea5a64', 0, 'CommodityVolatilities', 'CommodityVolatility', 'QuoteSuffix', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/QuoteSuffix', 6, 'string', false, 'Quote suffix', 'The allowable values are C and P indicating Call and Put respectively.', 'The allowable values are C and P indicating Call and Put respectively. If given, they are used in the construction of the commodity option quote strings as explained below. They are useful in cases where the market data contains both call and put volatility quotes for the same expiry strike pair and you want to use only the calls (set QuoteSuffix to C) or the puts (set QuoteSuffix to P).', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0b408c7d-240f-5443-b1f7-e2188889ab16', 0, 'CommodityVolatilities', 'CommodityVolatility', 'InstrumentType', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/InstrumentType', 7, 'string', false, 'Instrument type', 'Must be set to COMMODITY_CALENDAR_SPREAD_OPTION to indicate that this volatility configuration is for calendar spread options.', 'Must be set to COMMODITY_CALENDAR_SPREAD_OPTION to indicate that this volatility configuration is for calendar spread options. The default value is COMMODITY_OPTION (i.e.\ standard commodity options), so this node must be explicitly provided for calendar spread configurations.', 'COMMODITY_OPTION.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1d912f04-0c90-537a-99ea-8d62c3ba6c6b', 0, 'CommodityVolatilities', 'CommodityVolatility', 'CalendarSpreadOffset', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/CalendarSpreadOffset', 8, 'integer', false, 'Calendar spread offset', 'A positive integer indicating the futures contract offset for the calendar spread.', 'A positive integer indicating the futures contract offset for the calendar spread. A value of 1 means the spread is between the N-th and (N+1)-th futures contracts. This value must match the offset embedded in the CurveId.', '0.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a28cf349-e34b-5a78-b588-d6d17be2c918', 0, 'CommodityVolatilities', 'CommodityVolatility', 'CalendarSpreadUnderlyingName', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/CalendarSpreadUnderlyingName', 9, 'string', false, 'Calendar spread underlying name', 'The name of the underlying commodity for which the calendar spread is defined.', 'The name of the underlying commodity for which the calendar spread is defined. This must match the underlying portion of the CurveId. For example, if CurveId is ICE:B_CALENDAR_SPREAD_1, then CalendarSpreadUnderlyingName must be ICE:B.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '708ff354-2983-5469-b100-0f7c76d964af', 0, 'CommodityVolatilities', 'CommodityVolatility', 'DayCounter', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/DayCounter', 10, 'string', false, 'Day counter', 'The day count basis used internally by the curve to calculate the time between dates.', 'The day count basis used internally by the curve to calculate the time between dates. If omitted it defaults to A365.', 'A365.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f88f2ce1-63d3-5aa3-ad06-5046dcdc6d99', 0, 'CommodityVolatilities', 'CommodityVolatility', 'Calendar', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/Calendar', 11, 'string', false, 'Calendar', 'The calendar used internally by the volatility structure to amend dates generated from option tenors i.e.\ if a volatility is requested from the surface using an expiry tenor.', 'The calendar used internally by the volatility structure to amend dates generated from option tenors i.e.\ if a volatility is requested from the surface using an expiry tenor. If omitted it defaults to NullCalendar meaning there is no adjustment to the expiry on applying the option tenor.', 'NullCalendar meaning there is no adjustment to the expiry on applying the option tenor.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ec655660-534b-5bfb-a902-0571c89a7057', 0, 'CommodityVolatilities', 'CommodityVolatility', 'OptionExpiryRollDays', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/OptionExpiryRollDays', 12, 'integer', false, 'Option expiry roll days', 'The OptionExpiryRollDays can be any non-negative integer and may be needed when deriving an option expiry date from the Expiry portion of the commodity option quote.', 'The OptionExpiryRollDays can be any non-negative integer and may be needed when deriving an option expiry date from the Expiry portion of the commodity option quote. If the Expiry portion of the commodity option quote is a continuation expiry, an explicit expiry date is deduced as explained in the previous bullet point. Additionally, in some cases, the option quotes for the next option expiry may stop a number of business days before that option expiry and the cN expiry in this period begins referring to the N+1-th next option expiry. As an example, assume d_v is the valuation date and e_1 = d_v is the next option expiry date. If OptionExpiryRollDays is 0 then a commodity option quote with an Expiry portion equal to c1 on d_v indicates that the option quote is for an option with expiry date equal to e_1. However, if OptionExpiryRollDays is 1, a commodity option quote with an Expiry portion equal to c1 on d_v indicates that the option quote is for an option with expiry date equal to e_2 where e_2 is the next option expiry date after e_1. In other words, with OptionExpiryRollDays set to 1 the option quotes for expiry date e_1 stopped on the business day before e_1. If omitted, OptionExpiryRollDays defaults to 0.', '0.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd3114578-8613-5433-8fab-171bc23c4fe9', 0, 'CommodityVolatilities', 'CommodityVolatility', 'OneDimSolverConfig', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/OneDimSolverConfig', 13, 'string', false, 'One dim solver config', 'This is used if the QuoteType is Premium.', 'This is used if the QuoteType is Premium. It provides the options for the root search in the stripping of the volatilities from premia. If omitted, the default set of options shown in Listing are used. The MinMax node can be replaced with a single Step node that accepts a double giving the step size to use in the root search.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a29c23c2-0753-5d81-b2af-a7a91e080eea', 0, 'CommodityVolatilities', 'CommodityVolatility', 'PreferOutOfTheMoney', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/PreferOutOfTheMoney', 14, 'boolean', false, 'Prefer out of the money', 'A node accepting a boolean value.', 'A node accepting a boolean value. If set to true, quotes for out of the money options are preferred where a call and a put quote are found for the same expiry strike pair. If set to false, quotes for in the money options are preferred where a call and a put quote are found for the same expiry strike pair. If omitted, true is assumed.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a5bcad3c-d2bd-5f38-9acb-2714cf20d416', 0, 'CommodityVolatilities', 'CommodityVolatility/Report', 'Strikes', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/Report/Strikes', 21, 'string', false, 'Strikes', 'This can be a single wildcard value * or a comma separated list of explicit strike prices.', 'This can be a single wildcard value * or a comma separated list of explicit strike prices. We explain below how these strikes are combined with the other parameters in the configuration to give a list of commodity option quotes to search for in the market data.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9e5e5384-9e9b-56c4-80ff-f638bd07bdf2', 0, 'CommodityVolatilities', 'CommodityVolatility/Report', 'Expiries', 'curveconfig.xsd', '/CurveConfiguration/CommodityVolatilities/CommodityVolatility/Report/Expiries', 23, 'string', false, 'Expiries', 'This can be a single wildcard value * or a comma separated list of expiry strings.', 'This can be a single wildcard value * or a comma separated list of expiry strings. We explain below how these expiries are combined with the other parameters in the configuration to give a list of commodity option quotes to search for in the market data. Note that as outlined in Section , the Expiry portion of the commodity option quote may be an explicit expiry date, an expiry tenor or a continuation expiry of the form cN explained in the volatility curve section above.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5c5d02c9-f229-5e1d-a460-fdf00f51593c', 0, 'Correlations', 'Correlation', 'Calendar', 'curveconfig.xsd', '/CurveConfiguration/Correlations/Correlation/Calendar', 4, 'string', false, 'Calendar', 'The business day calendar for the deposit quote.', 'The business day calendar for the deposit quote.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f87ebcd3-d2af-5af8-9de5-f6e280980c29', 0, 'Correlations', 'Correlation', 'DayCounter', 'curveconfig.xsd', '/CurveConfiguration/Correlations/Correlation/DayCounter', 5, 'string', false, 'Day counter', 'The day count basis associated with the zero rate quote (for choices see section )', 'The day count basis associated with the zero rate quote (for choices see section )', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9412df1e-c3fd-5a36-bcfa-bd107cc197a3', 0, 'Correlations', 'Correlation', 'BusinessDayConvention', 'curveconfig.xsd', '/CurveConfiguration/Correlations/Correlation/BusinessDayConvention', 8, 'string', true, 'Business day convention', 'The business day convention used by the index.', 'The business day convention used by the index.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '24b3dc86-9793-516b-bb39-05a4dbfa1854', 0, 'Correlations', 'Correlation', 'Extrapolation', 'curveconfig.xsd', '/CurveConfiguration/Correlations/Correlation/Extrapolation', 9, 'string', true, 'Extrapolation', 'This can be FlatFwd or FlatZero.', 'This can be FlatFwd or FlatZero. If not given, the value defaults to FlatFwd.', 'FlatFwd.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '133a03af-579f-56dc-82e5-c69f17d2b92e', 0, 'Correlations', 'Correlation', 'Currency', 'curveconfig.xsd', '/CurveConfiguration/Correlations/Correlation/Currency', 12, 'string', true, 'Currency', 'The ISO currency code of the currency associated with the inflation index, generally the currency of the region.', 'The ISO currency code of the currency associated with the inflation index, generally the currency of the region.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b815789e-43a3-532c-8f9f-b0ad5748483f', 0, 'Correlations', 'Correlation', 'Conventions', 'curveconfig.xsd', '/CurveConfiguration/Correlations/Correlation/Conventions', 13, 'string', false, 'Conventions', 'The identifier for the conventions associated with the commodity being averaged.', 'The identifier for the conventions associated with the commodity being averaged.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd91446d1-f443-54d7-90b9-cf1114f7e299', 0, 'DefaultCurves', 'DefaultCurve', 'CurveId', 'curveconfig.xsd', '/CurveConfiguration/DefaultCurves/DefaultCurve/CurveId', 0, 'string', true, 'Curve id', 'Unique identifier for the bootstrapped default curve.', 'Unique identifier for the bootstrapped default curve. For index term curves a suffix _5Y should be appended to the name indicating the index term, since this is the preferred name looked up by index cds and index cds option pricers. If such a curve is not found, the pricers will fall back to the specified credit curve id without suffix, i.e. following this naming convention is not mandatory, but recommended.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b0f3b076-0743-5bae-a2a8-43cd4690ab43', 0, 'DefaultCurves', 'DefaultCurve', 'CurveDescription', 'curveconfig.xsd', '/CurveConfiguration/DefaultCurves/DefaultCurve/CurveDescription', 1, 'string', true, 'Curve description', 'A description of the default curve.', 'A description of the default curve. It is for information only and may be left blank.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '097fa696-66f2-55f4-b4eb-1a53802febb2', 0, 'DefaultCurves', 'DefaultCurve', 'Currency', 'curveconfig.xsd', '/CurveConfiguration/DefaultCurves/DefaultCurve/Currency', 2, 'string', true, 'Currency', 'The default curve''s currency.', 'The default curve''s currency.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f10df564-9e64-578d-a9d3-d1b16aa6286b', 0, 'EquityCurves', 'EquityCurve', 'CurveId', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/CurveId', 0, 'string', true, 'Curve id', 'Unique identifier of the equity curve structure.', 'Unique identifier of the equity curve structure.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '16f64ea5-d245-591f-98bd-d1a3bf019ad3', 0, 'EquityCurves', 'EquityCurve', 'CurveDescription', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/CurveDescription', 1, 'string', true, 'Curve description', 'A description of the equity curve structure, may be left blank.', 'A description of the equity curve structure, may be left blank.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e38574f9-e47e-50c9-816c-1161f4bc14c9', 0, 'EquityCurves', 'EquityCurve', 'ForecastingCurve', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/ForecastingCurve', 2, 'string', true, 'Forecasting curve', 'CurveId of the curve used for discounting equity fixing forecasts.', 'CurveId of the curve used for discounting equity fixing forecasts.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c103c1de-3dd4-5ed9-b588-aebaf6bfd123', 0, 'EquityCurves', 'EquityCurve', 'Currency', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/Currency', 3, 'string', true, 'Currency', 'Currency of the equity.', 'Currency of the equity.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '965d3e9d-e832-54ca-a38b-07e9d842af50', 0, 'EquityCurves', 'EquityCurve', 'Calendar', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/Calendar', 4, 'string', false, 'Calendar', 'The term structure''s calendar used in tenor to date conversions.', 'The term structure''s calendar used in tenor to date conversions. Defaults to the calendar corresponding to Currency.', 'the calendar corresponding to Currency.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c9f30e44-f093-54ab-9622-e2c7cebda408', 0, 'EquityCurves', 'EquityCurve', 'Type', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/Type', 5, 'string', true, 'Type', 'The quote types in Quote (e.g.\ option premium, forward equity price) and whether dividends are taken into account.', 'The quote types in Quote (e.g.\ option premium, forward equity price) and whether dividends are taken into account. Allowable values: DividendYield, ForwardPrice, ForwardDividendPrice, OptionPremium, NoDividends', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ffa07f42-42fc-5299-bc45-595b449dc338', 0, 'EquityCurves', 'EquityCurve', 'ExerciseStyle', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/ExerciseStyle', 6, 'string', true, 'Exercise style', 'Exercise type of the underlying option quotes.', 'Exercise type of the underlying option quotes. Only required if Type is OptionPremium. Allowable values: American, European', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c4fa758b-a99b-562e-97d3-5b70631b6785', 0, 'EquityCurves', 'EquityCurve', 'SpotQuote', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/SpotQuote', 7, 'string', true, 'Spot quote', 'Market datum ID/name of the current spot rate for the equity underlying.', 'Market datum ID/name of the current spot rate for the equity underlying.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '374746f5-ae97-550f-87dd-87d9280d5d5d', 0, 'EquityCurves', 'EquityCurve', 'DayCounter', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/DayCounter', 8, 'string', false, 'Day counter', 'The term structure''s day counter used in date to time conversions.', 'The term structure''s day counter used in date to time conversions. Defaults to A365F.', 'A365F.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '50e6ce0c-10b3-5694-9650-f7779e4b127e', 0, 'EquityCurves', 'EquityCurve', 'Quotes', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/Quotes', 9, 'string', false, 'Quotes', 'Market datum IDs/names to be used in building the curve structure.', 'Market datum IDs/names to be used in building the curve structure.', 'Quote.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '697c17ee-75ef-5ab8-9562-5428cd49f549', 0, 'EquityCurves', 'EquityCurve', 'DividendExtrapolation', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/DividendExtrapolation', 10, 'boolean', false, 'Dividend extrapolation', 'Boolean flag indicating whether extrapolation in the dividend curve is allowed.', 'Boolean flag indicating whether extrapolation in the dividend curve is allowed. If True the dividend curve is extrapolated forward at the risk free rate beyond the last date of the curve - this is only considered when Extrapolation is False. Defaults to False.', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '423507db-56a6-50cb-8089-3ac64e46f9ca', 0, 'EquityCurves', 'EquityCurve', 'Extrapolation', 'curveconfig.xsd', '/CurveConfiguration/EquityCurves/EquityCurve/Extrapolation', 11, 'boolean', false, 'Extrapolation', 'Boolean flag indicating whether extrapolation in the forward price is allowed.', 'Boolean flag indicating whether extrapolation in the forward price is allowed. Defaults to False.', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '94992d53-d397-542d-9846-5f78677b2577', 0, 'EquityVolatilities', 'EquityVolatility', 'CurveId', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/CurveId', 0, 'string', true, 'Curve id', 'Unique identifier for the curve.', 'Unique identifier for the curve.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'cf30428f-6c3d-52ae-9b3b-cbb98c9ec5d7', 0, 'EquityVolatilities', 'EquityVolatility', 'CurveDescription', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/CurveDescription', 1, 'string', true, 'Curve description', 'A description of the curve.', 'A description of the curve. This field may be left blank.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dfea5438-f1cd-5a69-ba90-bee1a1284220', 0, 'EquityVolatilities', 'EquityVolatility', 'EquityId', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/EquityId', 2, 'string', false, 'Equity id', '[Optional] Identifies the underlying equity name, this is used in the construction of the Quote strings.', '[Optional] Identifies the underlying equity name, this is used in the construction of the Quote strings. If omitted the CurveId is used instead.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dc02b5fb-9198-5750-ba55-6733a30e518a', 0, 'EquityVolatilities', 'EquityVolatility', 'Currency', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/Currency', 3, 'string', true, 'Currency', 'Currency of the equity.', 'Currency of the equity.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd1228df6-c9f8-5564-8e10-6cf33b85ae9d', 0, 'EquityVolatilities', 'EquityVolatility', 'Calendar', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/Calendar', 4, 'string', false, 'Calendar', 'allowable value is any valid calendar.', 'allowable value is any valid calendar. Defaults to NullCalendar.', 'NullCalendar.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a7e1a521-69af-5827-8c2b-20e3d2cf3433', 0, 'EquityVolatilities', 'EquityVolatility', 'Expiries', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/Expiries', 6, 'string', true, 'Expiries', 'comma separated list of expiry tenors and or expiry dates.', 'comma separated list of expiry tenors and or expiry dates. A single wildcard character, *, can be used here also to indicate that all expiries found in the market data for this equity volatility configuration should be used when building the equity volatility surface.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '42a1da1b-4034-5d73-9f26-3adf05365706', 0, 'EquityVolatilities', 'EquityVolatility', 'TimeExtrapolation', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/TimeExtrapolation', 7, 'string', true, 'Time extrapolation', 'extrapolation in the option expiry direction.', 'extrapolation in the option expiry direction. If both Strikes and Expiries are configured explicitly, the extrapolation in the time direction is flat in volatility regardless of the setting here. If either Strikes or Expiries are configured with a wildcard character, Linear, UseInterpolator, Flat or None are allowed. If Linear or UseInterpolator is specified, the extrapolation is linear. If Flat is specified, the extrapolation is flat. If None is specified, it is ignored and the extrapolation is flat since extrapolation in the time direction cannot be turned off in isolation i.e.\ extrapolation can only be turned off for the surface as a whole using the Extrapolation flag.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3755f498-472d-52ca-9322-220bdfda676a', 0, 'EquityVolatilities', 'EquityVolatility', 'StrikeExtrapolation', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/StrikeExtrapolation', 8, 'string', true, 'Strike extrapolation', 'extrapolation in the strike direction.', 'extrapolation in the strike direction. The allowable values are Linear, UseInterpolator, Flat or None. If Linear or UseInterpolator is specified, the extrapolation uses the strike interpolation setting for extrapolation i.e. linear or cubic in this case. If Flat is specified, the extrapolation is flat. If None is specified, it is ignored and the extrapolation is flat since extrapolation in the strike direction cannot be turned off in isolation i.e.\ extrapolation can only be turned off for the surface as a whole using the Extrapolation flag.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c09c110a-2030-5d5b-b2a7-b8b75a95bbce', 0, 'EquityVolatilities', 'EquityVolatility', 'Strikes', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/Strikes', 9, 'string', false, 'Strikes', 'comma separated list of strikes, representing the absolute strike values for the option.', 'comma separated list of strikes, representing the absolute strike values for the option. In other words, A single wildcard character, *, can be used here also to indicate that all strikes found in the market data for this equity volatility configuration should be used when building the equity volatility surface.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '21cb667e-b593-5c1e-852f-1d20c3f34656', 0, 'EquityVolatilities', 'EquityVolatility', 'OneDimSolverConfig', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/OneDimSolverConfig', 10, 'string', false, 'One dim solver config', 'A configuration for the one dimensional solver used in deriving volatilities from prices.', 'A configuration for the one dimensional solver used in deriving volatilities from prices. This node is described in detail in Section . If not provided, a default step based configuration is used. This is only used when volatilities are stripped from prices.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ed8d53ad-746e-5498-a034-a66462070f31', 0, 'EquityVolatilities', 'EquityVolatility', 'PreferOutOfTheMoney', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/PreferOutOfTheMoney', 11, 'boolean', false, 'Prefer out of the money', 'allowable value is any boolean value.', 'allowable value is any boolean value. Defaults to false for backwards compatibility. It is used, when building the volatility surface, to choose between a call and put option price or volatility when both are provided. When set to true, the out of the money option is chosen by comparing the quote''s strike with the forward price at the associated expiry. Conversely, when set to false, the in the money option is chosen.', 'false for backwards compatibility.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '68423901-11b6-5e92-82ea-45175bf4adae', 0, 'EquityVolatilities', 'EquityVolatility/Report', 'Strikes', 'curveconfig.xsd', '/CurveConfiguration/EquityVolatilities/EquityVolatility/Report/Strikes', 18, 'string', false, 'Strikes', 'comma separated list of strikes, representing the absolute strike values for the option.', 'comma separated list of strikes, representing the absolute strike values for the option. In other words, A single wildcard character, *, can be used here also to indicate that all strikes found in the market data for this equity volatility configuration should be used when building the equity volatility surface.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
