        (v_dataset_id, ores_utility_system_tenant_id_fn(), '21036dc5-e562-59e6-a006-190a1e98773c', 0, 'FXVolatilities', 'FXVolatility', 'CurveId', 'curveconfig.xsd', '/CurveConfiguration/FXVolatilities/FXVolatility/CurveId', 0, 'string', true, 'Curve id', 'Unique identifier of the FX volatility structure', 'Unique identifier of the FX volatility structure', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
