        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd71559ed-6349-5c3f-a2ac-4283082f26ad', 0, 'FXVolatilities', 'FXVolatility', 'Calendar', 'curveconfig.xsd', '/CurveConfiguration/FXVolatilities/FXVolatility/Calendar', 3, 'string', false, 'Calendar', 'The term structure''s calendar used in option tenor to date conversions.', 'The term structure''s calendar used in option tenor to date conversions. Optional, defaults to source ccy + target ccy default calendars.', 'source ccy + target ccy default calendars.', 'Text.', '1.8.0.7 or earlier', null),
