        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1894ccf7-490c-5107-91ba-741222e86373', 0, 'SwaptionVolatilities', 'SwaptionVolatility', 'OutputVolatilityType', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/OutputVolatilityType', 4, 'string', false, 'Output volatility type', 'Optional, defaults to input volatility type.', 'Optional, defaults to input volatility type. Possible values: Normal, Lognormal (alias for ShiftedLognormal, shift is taken from OutputShift if given, or input market data shift. Input market quotes will be converted to output volatility type and shift before building the vol surfaces, except for parametric models (SABR), where the model is calibrated to the input market data directly (without conversion) and the output volatility type and shift is handled by the calibrated parametric model. An early conversion of the input market data would not be an advantage in this case, we could only loose information.', 'input volatility type.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '48355837-ba37-5a91-89af-507a46e5d2a6', 0, 'SwaptionVolatilities', 'SwaptionVolatility', 'ModelShift', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/ModelShift', 5, 'string', false, 'Model shift', 'Optional, defaults to input market data shift.', 'Optional, defaults to input market data shift. Specifies the shift used for SABR model if applicable', 'input market data shift.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f216462f-349e-5469-98a5-3ff0f9c21e8f', 0, 'SwaptionVolatilities', 'SwaptionVolatility', 'OutputShift', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/OutputShift', 6, 'string', false, 'Output shift', 'Optional, defaults to input market data shift.', 'Optional, defaults to input market data shift. Specifies the shift if OutputVolatilityType is Lognormal / ShiftedLognormal', 'input market data shift.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e6f03a35-2655-5f18-a041-f51f6cb8d290', 0, 'SwaptionVolatilities', 'SwaptionVolatility', 'Interpolation', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/Interpolation', 7, 'string', false, 'Interpolation', 'Optional.', 'Optional. Possible values: Linear, Hagan2002Lognormal, Hagan2002Normal, Hagan2002NormalZeroBeta, Antonov2015FreeBoundaryNormal, KienitzLawsonSwaynePde, FlochKennedyFlochKennedy shows unstable results and is considered experimental. More work is needed.. If not given, defaults to Linear.', 'Linear.', 'Text.', '1.8.0.7 or earlier', null),
