        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd170c61f-fe20-52cf-ac19-f7fe0add7cf4', 0, 'SwaptionVolatilities', 'SwaptionVolatility', 'SmileSpreads', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/SmileSpreads', 16, 'string', true, 'Smile spreads', 'Strikes in smile direction expressed as strike spreads, relative to the ATM strike at the expiry/term point of the ATM matrix.', 'Strikes in smile direction expressed as strike spreads, relative to the ATM strike at the expiry/term point of the ATM matrix. Note that trailing 0s are not ignored.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f8ee8379-8726-5399-9bfd-5860287574cf', 0, 'SwaptionVolatilities', 'SwaptionVolatility', 'QuoteTag', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/QuoteTag', 17, 'string', false, 'Quote tag', 'If non-empty, a tag will be included in the market datum labels.', 'If non-empty, a tag will be included in the market datum labels. This can be used to set up underlying specific volatility date. For example, if the quote tag is set to EUR-EURIBOR-3M, the market datum labels will be +SWAPTION/RATE_LNVOL/EUR/EUR-EURIBOR-3M/5Y/10Y/ATM+ instead of +SWAPTION/RATE_LNVOL/EUR/5Y/10Y/ATM+. See section .', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '92d72e40-f30e-5a0f-996c-114a1e34de4f', 0, 'SwaptionVolatilities', 'SwaptionVolatility', 'SwapTenors', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/SwapTenors', 18, 'string', false, 'Swap tenors', 'Underlying Swap term in period form', 'Underlying Swap term in period form', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4088a86e-d01f-5552-8a50-7054f4f4adcf', 0, 'SwaptionVolatilities', 'SwaptionVolatility', 'SmileSwapTenors', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/SmileSwapTenors', 19, 'string', false, 'Smile swap tenors', 'Underlying Swap term, in period form, where smile section data is to be taken into account', 'Underlying Swap term, in period form, where smile section data is to be taken into account', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8f4fae5c-fede-5b7a-88ec-d851a0fda0d6', 0, 'SwaptionVolatilities', 'SwaptionVolatility/ParametricSmileConfiguration/ResidualCorrection', 'Dimension', 'curveconfig.xsd', '/CurveConfiguration/SwaptionVolatilities/SwaptionVolatility/ParametricSmileConfiguration/ResidualCorrection/Dimension', 23, 'string', true, 'Dimension', 'Distinguishes at-the-money matrices and full volatility cubes.', 'Distinguishes at-the-money matrices and full volatility cubes. Allowable values: ATM, Smile', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '606bd825-0a17-53a3-ab0b-c5fa43dda9f7', 0, 'YieldCurves', 'YieldCurve', 'CurveId', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/CurveId', 0, 'string', true, 'Curve id', 'Unique identifier for the yield curve.', 'Unique identifier for the yield curve.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'dfbb9013-2bdb-54ee-a2d0-ba8a939785d3', 0, 'YieldCurves', 'YieldCurve', 'CurveDescription', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/CurveDescription', 1, 'string', true, 'Curve description', 'A description of the yield curve.', 'A description of the yield curve. This field may be left blank.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '414c9956-c141-5500-ae1e-b628904aa54d', 0, 'YieldCurves', 'YieldCurve', 'Currency', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/Currency', 2, 'string', true, 'Currency', 'The yield curve currency.', 'The yield curve currency.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bd8c943a-ea5a-5b04-9a1e-beedac690188', 0, 'YieldCurves', 'YieldCurve', 'DiscountCurve', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/DiscountCurve', 3, 'string', true, 'Discount curve', 'If the yield curve is being bootstrapped from market instruments, this gives the CurveId of the yield curve used to discount cash flows during the bootstrap procedure.', 'If the yield curve is being bootstrapped from market instruments, this gives the CurveId of the yield curve used to discount cash flows during the bootstrap procedure. If this field is left blank or set equal to the current CurveId, then this yield curve itself is used to discount cash flows during the bootstrap procedure.', 'None: the curve must give it.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0e49f69d-b1df-57a8-9456-a37e126d9274', 0, 'YieldCurves', 'YieldCurve', 'InterpolationVariable', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/InterpolationVariable', 4, 'string', false, 'Interpolation variable', 'The variable on which the interpolation is performed.', 'The variable on which the interpolation is performed. The allowable values are given in the guide. If the element is omitted or left blank, then it defaults to Discount.', 'Discount.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ed08796d-8510-5ded-baba-2cb56dadd317', 0, 'YieldCurves', 'YieldCurve', 'InterpolationMethod', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/InterpolationMethod', 5, 'string', false, 'Interpolation method', 'The interpolation method to use.', 'The interpolation method to use. The allowable values are given in the guide. If the element is omitted or left blank, then it defaults to LogLinear.', 'LogLinear.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b396a105-dfb1-5b0e-807c-ff3f011be5c8', 0, 'YieldCurves', 'YieldCurve', 'MixedInterpolationCutoff', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/MixedInterpolationCutoff', 6, 'integer', false, 'Mixed interpolation cutoff', 'If a mixed interpolation method is used, the number of segments to which the first interpolation method is applied.', 'If a mixed interpolation method is used, the number of segments to which the first interpolation method is applied. Defaults to 1.', '1.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7af25ba0-1e49-5aa8-be1d-4e6202cf44e3', 0, 'YieldCurves', 'YieldCurve', 'YieldCurveDayCounter', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/YieldCurveDayCounter', 7, 'string', false, 'Yield curve day counter', 'The day count basis used internally by the yield curve to calculate the time between dates.', 'The day count basis used internally by the yield curve to calculate the time between dates. In particular, if the curve is queried for a zero rate without specifying the day count basis, the zero rate that is returned has this basis. If the element is omitted or left blank, then it defaults to A365.', 'A365.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6a14ce81-ba89-5a3e-8f7a-5b50666046cc', 0, 'YieldCurves', 'YieldCurve', 'Extrapolation', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/Extrapolation', 8, 'boolean', false, 'Extrapolation', 'Set to True or False to enable or disable extrapolation respectively.', 'Set to True or False to enable or disable extrapolation respectively. If the element is omitted or left blank, then it defaults to True.', 'true.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f69efafd-ce6f-54ab-9f20-9b72a34a0f04', 0, 'YieldCurves', 'YieldCurve', 'ExtrapolationMethod', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/ExtrapolationMethod', 9, 'string', false, 'Extrapolation method', 'Only applies to bootstrapped curves and interpolated zero / discount curves.', 'Only applies to bootstrapped curves and interpolated zero / discount curves. Controls how the curve is extrapolated: itemize', 'ContinuousForward.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '37e38d52-93f4-5b8a-87c8-9d351e945132', 0, 'YieldCurves', 'YieldCurve', 'ExcludeT0FromInterpolation', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/ExcludeT0FromInterpolation', 10, 'boolean', false, 'Exclude t 0 from interpolation', 'Only applies to bootstrapped curves and interpolated zero / discount curves.', 'Only applies to bootstrapped curves and interpolated zero / discount curves. Set to True to exclude the synthetic time-zero (t0) point from yield curve interpolation. When enabled, the curve interpolates only on actual market pillar dates, while still ensuring proper behavior at the reference date (e.g., DF(t_0) = 1.0 for discount curves). This is useful when the first market pillar date does not coincide with the as-of date and you want to avoid including a synthetic point in the interpolation. This feature is supported for all three interpolation variables: itemize', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6e736c74-3fe2-5837-a2cf-ec17452a5dcd', 0, 'YieldCurves', 'YieldCurve', 'Tolerance', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/Tolerance', 11, 'double', false, 'Tolerance', 'The tolerance used by the root finding procedure in the bootstrapping algorithm.', 'The tolerance used by the root finding procedure in the bootstrapping algorithm. If the element is omitted or left blank, then it defaults to 1.0e-12. It is preferable to use the', '1.0e-12.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a9d00534-8f52-5a87-8ea6-e749859b0b5e', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'Accuracy', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/Accuracy', 12, 'double', false, 'Accuracy', 'the desired accuracy expressed as a weighted rmse in the implied quote, where 0.01 = 1 bp.', 'the desired accuracy expressed as a weighted rmse in the implied quote, where 0.01 = 1 bp. Once this accuracy is reached in a calibration trial, the fit is accepted, no further calibration trials re run. In general, this parameter should be set to a higher than the default value for fitted bond curves.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5b65257f-9824-5b04-b22d-70844c84b5d0', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'GlobalAccuracy', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/GlobalAccuracy', 13, 'double', false, 'Global accuracy', 'the acceptable accuracy.', 'the acceptable accuracy. If the Accuracy is not reached in any calibration trial, but the GlobalAccuracy is met, the best fit among the calibration trials is selected as a result of the calibration. If not given, the best calibration trial is compared to the Accuracy parameter instead.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1786de07-6fbd-5955-aa68-7a286a9644c5', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'DontThrow', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/DontThrow', 14, 'boolean', false, 'Dont throw', 'If true, the best calibration is always accepted as a result, i.e.', 'If true, the best calibration is always accepted as a result, i.e. no error is thrown even if the GlobalAccuracy is breached.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b8d796d3-fa13-5243-9df3-ff10922f1596', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'MaxAttempts', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/MaxAttempts', 15, 'integer', false, 'Max attempts', 'The maximum number of calibration trials.', 'The maximum number of calibration trials. Each calibration trial is run with a random calibration seed. Random calibration seeds are currently only supported for the NelsonSiegel interpolation method.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a09206ad-8ed8-5239-910e-b5177f590f9f', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'MaxFactor', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/MaxFactor', 16, 'double', false, 'Max factor', 'This node is used only if MaxAttempts is greater than 1.', 'This node is used only if MaxAttempts is greater than 1. The meaning of this node is given in the description of the MaxAttempts node. This node should hold a positive real number. If omitted, the default value is 2.0.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ef7e6aeb-41f4-5ce4-83ec-78efae9f2b77', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'MinFactor', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/MinFactor', 17, 'double', false, 'Min factor', 'This node is used only if MaxAttempts is greater than 1.', 'This node is used only if MaxAttempts is greater than 1. The meaning of this node is given in the description of the MaxAttempts node. This node should hold a positive real number. If omitted, the default value is 2.0.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '048297db-4fb5-55da-b29b-a49a183ce2e7', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'DontThrowSteps', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/DontThrowSteps', 18, 'integer', false, 'Dont throw steps', 'This node is used only if DontThrow is true.', 'This node is used only if DontThrow is true. The meaning of this node is given in the description of the DontThrow node. This node should hold a positive integer. If omitted, the default value is 10.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '409dfd3f-27d1-5a30-b991-912da26c18e3', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'Global', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/Global', 19, 'boolean', false, 'Global', 'Defaults to false.', 'Defaults to false. This nodes specifies whether the curve should use a global bootstrap over all instruments of the curve (true) or iterative bootstrap (false, default value). If global bootstrap is used, only the fields Accuracy and SmoothnessLambda of the BootstrapConfig are relevant. Accurcy specifies the accuracy of the global optimizer in this case. Global bootstrap is required to build curves that form a cycle in the dependency graph, in this case all members of the cycle must have Global set to true in their bootstrap configs. In this case a global optimization is run over all instrument of all members of the cycle simultaneously. Global bootstrap is also required if according to the PillarChoice configuration of each segment there are curve instrument without or with more than one associated curve pillar date. Finally, global bootstrap can be preferable over iterative bootstrap if the latter requires an outer convergence loop, i.e. if a pillar choice is not set to LastRelevatDate or if the interpolation is non-local.', 'false.', 'true or false.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'afe39c5b-22af-5161-a005-f8792f27ee5b', 0, 'YieldCurves', 'YieldCurve/BootstrapConfig', 'SmoothnessLambda', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/BootstrapConfig/SmoothnessLambda', 20, 'double', false, 'Smoothness lambda', 'Defaults to zero.', 'Defaults to zero. Only applies if GLobal is set to true. If positive, penalty components are included in the global optimization used to build a curve. For each adjacent pair of discrete forward rates F_i, F_i+1 between curve interpolation pillars, the term (F_i+1 - F_i) is added to the target function vector of which the MSE is optimized.', 'zero.', 'A number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2b7d52e7-ee82-5bea-9eed-246c2ff64f96', 0, 'YieldCurves', 'YieldCurve/Segments/Direct', 'Conventions', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/Segments/Direct/Conventions', 34, 'string', false, 'Conventions', 'The identifier for the conventions associated with the commodity being averaged.', 'The identifier for the conventions associated with the commodity being averaged.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1682f534-b2ff-55ef-886c-706d91d462f5', 0, 'YieldCurves', 'YieldCurve/Segments/Direct', 'PillarChoice', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/Segments/Direct/PillarChoice', 35, 'string', false, 'Pillar choice', 'Which date of each instrument becomes its bootstrap pillar: MaturityDate, LastRelevantDate, NoPillar, StartDate, StartDateAndMaturityDate or StartDateAndLastRelevantDate.', 'Which date of each instrument becomes its bootstrap pillar: MaturityDate, LastRelevantDate, NoPillar, StartDate, StartDateAndMaturityDate or StartDateAndLastRelevantDate.', 'LastRelevantDate.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6487a358-a6fb-57cc-8a5b-5f53af7dd1f7', 0, 'YieldCurves', 'YieldCurve/Segments/Direct', 'DuplicatePillarPolicy', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/Segments/Direct/DuplicatePillarPolicy', 36, 'string', false, 'Duplicate pillar policy', 'How the bootstrap treats instruments in the same segment that share a pillar date: KeepLast, KeepFirst, KeepAll or ThrowError.', 'How the bootstrap treats instruments in the same segment that share a pillar date: KeepLast, KeepFirst, KeepAll or ThrowError.', 'KeepLast.', 'Text.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6716cd10-9c9f-5f22-ad32-e90258a58776', 0, 'YieldCurves', 'YieldCurve/Segments/Direct', 'Priority', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/Segments/Direct/Priority', 37, 'integer', false, 'Priority', 'The segment''s place in the bootstrap order, as a non-negative integer where a lower number is a higher priority.', 'The segment''s place in the bootstrap order, as a non-negative integer where a lower number is a higher priority. When two adjacent segments overlap on pillar dates, the instruments of the lower-priority segment are removed until the overlap is resolved.', '0.', 'A whole number.', '1.8.0.7 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fef41610-444e-5de3-b66e-104e6a6aeea7', 0, 'YieldCurves', 'YieldCurve/Segments/Direct', 'MinDistance', 'curveconfig.xsd', '/CurveConfiguration/YieldCurves/YieldCurve/Segments/Direct/MinDistance', 38, 'integer', false, 'Minimum distance', 'The number of calendar days kept between the pillar dates of this segment and the next one, when the two segments overlap.', 'The number of calendar days kept between the pillar dates of this segment and the next one, when the two segments overlap.', '1.', 'A whole number.', '1.8.0.7 or earlier', null),
