        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ed6e134b-ed64-5a32-9ebd-fafb8fe1c385', 0, 'instrument', 'EquityMarginLegData.Rates', 'Rate', 'instruments.xsd', '/EquityMarginLegData/Rates/Rate', 0, 'list:EquityMarginLegData.Rates.Rate', true, 'Rate', 'The Rate element of Rates, which the ORE user guide does not describe.', 'The Rate element of Rates, which the ORE user guide does not describe.', 'None: the trade must give it.', 'A rate record, repeated.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'be109bd6-70f7-5dec-b877-c89547fcc507', 0, 'instrument', 'EquityMarginLegData.Rates.Rate', 'startDate', 'instruments.xsd', '/EquityMarginLegData/Rates/Rate/@startDate', 0, 'string', false, 'Start date', 'The startDate attribute of Rate, which the ORE user guide does not describe.', 'The startDate attribute of Rate, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7988bf34-d69b-5637-a3c2-2cc4b261db54', 0, 'instrument', 'ExerciseDates', 'ExerciseDate', 'instruments.xsd', '/ExerciseDates/ExerciseDate', 0, 'list:string', false, 'Exercise date', 'The ExerciseDate element of ExerciseDates, which the ORE user guide does not describe.', 'The ExerciseDate element of ExerciseDates, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text, repeated.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '778b6a08-4083-5d7b-b9bb-26311fd09c82', 0, 'instrument', 'FixedLegData', 'Rates', 'instruments.xsd', '/FixedLegData/Rates', 0, 'record:FixedLegData.Rates', true, 'Rates', 'This node contains child elements of type Rate.', 'This node contains child elements of type Rate. If the rate is constant over the life of the fixed leg, only one rate value should be entered. If two or more coupons have different rates, multiple rate values are required, each represented by a Rate child element. The first rate value corresponds to the first coupon, the second rate value corresponds to the second coupon, etc. If the number of coupons exceeds the number of rate values, the rate will be kept flat at the value of last entered rate for the remaining coupons. The number of entered rate values cannot exceed the number of coupons. Allowable values: Each child element can take any real number. The rate is expressed in decimal form, e.g. 0.05 is a rate of 5%. As in the case of notionals, the rate schedule can be specified with dates as shown in Listing the guide. \begin{listing}[H] %\hrule\medskip \begin{minted}[fontsize=\footnotesize]{xml} <FixedLegData> <Rates> <Rate>0.05</Rate> <Rate startDate=''2016-02-04''>0.05</Rate> <Rate startDate=''2019-02-05''>0.05</Rate> </Rates> </FixedLegData>', 'None: the trade must give it.', 'A rates record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2159615d-f2b7-53d3-80fa-e6e5cdfa032e', 0, 'instrument', 'FixedLegData.Rates', 'Rate', 'instruments.xsd', '/FixedLegData/Rates/Rate', 0, 'list:FixedLegData.Rates.Rate', false, 'Rate', 'The Rate element of Rates, which the ORE user guide does not describe.', 'The Rate element of Rates, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'A rate record, repeated.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '74e668f4-8928-504b-abc2-f7e886bf10f2', 0, 'instrument', 'FixedLegData.Rates.Rate', 'startDate', 'instruments.xsd', '/FixedLegData/Rates/Rate/@startDate', 0, 'string', false, 'Start date', 'The startDate attribute of Rate, which the ORE user guide does not describe.', 'The startDate attribute of Rate, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7f5cb1c7-cf54-5af7-a79f-1ca003c3e07e', 0, 'instrument', 'FloatingLegData', 'Index', 'instruments.xsd', '/FloatingLegData/Index', 0, 'string', true, 'Index', 'The combination of currency, index and term that identifies the relevant fixings and yield curve of the floating leg.', 'The combination of currency, index and term that identifies the relevant fixings and yield curve of the floating leg. Allowable values: An alphanumeric string of the form CCY-INDEX-TENOR. CCY, INDEX and TENOR must be separated by dashes (-). CCY and INDEX must be among the supported currency and index combinations. TENOR must be an integer followed by D, W, M or Y. See Table the guide. TENOR is not required for Overnight indices, but can be set to 1D.', 'None: the trade must give it.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a7fb7f19-b02a-551c-9b32-dd14266a0021', 0, 'instrument', 'FloatingLegData', 'IsInArrears', 'instruments.xsd', '/FloatingLegData/IsInArrears', 1, 'boolean', false, 'Is in arrears', 'true indicates that fixing is in arrears, false indicates that fixing is in advance.', 'true indicates that fixing is in arrears, false indicates that fixing is in advance. \begin{itemize}', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '66f3f1b3-1fda-5ef5-96dc-613ad3c9913e', 0, 'instrument', 'FloatingLegData', 'LastRecentPeriod', 'instruments.xsd', '/FloatingLegData/LastRecentPeriod', 2, 'string', false, 'Last recent period', 'The LastRecentPeriod element of FloatingLegData, which the ORE user guide does not describe.', 'The LastRecentPeriod element of FloatingLegData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '20121546-13ff-5e70-a197-c56094a173c9', 0, 'instrument', 'FloatingLegData', 'LastRecentPeriodCalendar', 'instruments.xsd', '/FloatingLegData/LastRecentPeriodCalendar', 3, 'string', false, 'Last recent period calendar', 'The LastRecentPeriodCalendar element of FloatingLegData, which the ORE user guide does not describe.', 'The LastRecentPeriodCalendar element of FloatingLegData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '427313cd-cb38-5eef-a195-f448df868704', 0, 'instrument', 'FloatingLegData', 'FixingDays', 'instruments.xsd', '/FloatingLegData/FixingDays', 4, 'integer', false, 'Fixing days', 'The FixingDays element of FloatingLegData, which the ORE user guide does not describe.', 'The FixingDays element of FloatingLegData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0e9d5613-d682-5782-9c6f-4573a94568ea', 0, 'instrument', 'FloatingLegData', 'Lookback', 'instruments.xsd', '/FloatingLegData/Lookback', 5, 'string', false, 'Lookback', 'The Lookback element of FloatingLegData, which the ORE user guide does not describe.', 'The Lookback element of FloatingLegData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ca8188b8-be8d-56e5-b760-e61a2bba7f13', 0, 'instrument', 'FloatingLegData', 'RateCutoff', 'instruments.xsd', '/FloatingLegData/RateCutoff', 6, 'integer', false, 'Rate cutoff', 'The RateCutoff element of FloatingLegData, which the ORE user guide does not describe.', 'The RateCutoff element of FloatingLegData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1792bae7-fa12-59d1-8621-b33fc21634c3', 0, 'instrument', 'FloatingLegData', 'IsAveraged', 'instruments.xsd', '/FloatingLegData/IsAveraged', 7, 'boolean', false, 'Is averaged', 'For cases where there are multiple index fixings over a period true indicates that the average of the fixings is used to calculate the coupon.', 'For cases where there are multiple index fixings over a period true indicates that the average of the fixings is used to calculate the coupon. false indicates that the coupon is calculated by compounding the fixings. IsAveraged only applies to Overnight indices and Sub Periods Coupons. Allowable values: true, false. Defaults to false if left blank or omitted.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '08c7adf3-32d1-5752-825c-ffa3828fc0c1', 0, 'instrument', 'FloatingLegData', 'HasSubPeriods', 'instruments.xsd', '/FloatingLegData/HasSubPeriods', 8, 'boolean', false, 'Has sub periods', 'For cases where several Ibor fixings result in a single payment for a period, e.g.', 'For cases where several Ibor fixings result in a single payment for a period, e.g. if the Ibor tenor is 3M and the schedule tenor is 6M, two fixings are used to compute the amount of the semiannual coupon payments. true indicates that an average (IsAveraged = true) or a compounded (IsAveraged=false) value of the fixings is used to determine the payment rate. false indicates that the initial index period fixing determines the payment rate for the full tenor, i.e. no further fixings, no averaging and no compounding. IsAveraged is ignored for Ibor legs when HasSubPeriods is set to false. HasSubPeriods does not apply to Overnight indices. Allowable values: true, false. Defaults to false if left blank or omitted.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6174e279-432a-5402-83d8-e7666bbd8817', 0, 'instrument', 'FloatingLegData', 'IncludeSpread', 'instruments.xsd', '/FloatingLegData/IncludeSpread', 9, 'boolean', false, 'Include spread', 'Only applies to Sub Periods and (compounded) OIS Coupons.', 'Only applies to Sub Periods and (compounded) OIS Coupons. If true the spread is included in the compounding, otherwise it is excluded. Allowable values: true, false. Defaults to false if left blank or omitted. A Zero Coupon Floating leg with compounding that includes spread can be set up using a rules-based schedule as shown in Listing the guide. Note that the Tenor in the rules-based schedule is not used when Rule is set to Zero. \begin{listing}[H] %\hrule\medskip \begin{minted}[fontsize=\footnotesize]{xml} <LegData> <LegType>Floating</LegType> <Payer>false</Payer> <Currency>USD</Currency> <Notionals> <Notional>200000.0000</Notional> </Notionals> <DayCounter>A360</DayCounter> <PaymentConvention>MF</PaymentConvention> <ScheduleData> <Rules> <StartDate>2020-01-14</StartDate> <EndDate>2020-07-14</EndDate> <Tenor>3M</Tenor> <Calendar>USD</Calendar> <Convention>MF</Convention> <TermConvention>MF</TermConvention> <Rule>Zero</Rule> </Rules> </ScheduleData> <FloatingLegData> <Index>USD-LIBOR-3M</Index> <IsAveraged>false</IsAveraged> <HasSubPeriods>true</HasSubPeriods> <IncludeSpread>true</IncludeSpread> <Spreads> <Spread>0.006500</Spread> </Spreads> <IsInArrears>false</IsInArrears> <FixingDays>2</FixingDays> </FloatingLegData> </LegData>', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fd4270a7-5344-5bac-9e5e-1a8fbc5581dc', 0, 'instrument', 'FloatingLegData', 'IsNotResettingXCCY', 'instruments.xsd', '/FloatingLegData/IsNotResettingXCCY', 10, 'boolean', false, 'Is not resetting XCCY', 'The IsNotResettingXCCY element of FloatingLegData, which the ORE user guide does not describe.', 'The IsNotResettingXCCY element of FloatingLegData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e7b70300-b5be-5dcc-9d2d-67a15121da79', 0, 'instrument', 'FloatingLegData', 'Spreads', 'instruments.xsd', '/FloatingLegData/Spreads', 11, 'record:spreads', false, 'Spreads', 'The Spreads element of FloatingLegData, which the ORE user guide does not describe.', 'The Spreads element of FloatingLegData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'A spreads record.', '1.8.17.0 or earlier', null),
