        (v_dataset_id, ores_utility_system_tenant_id_fn(), '973ef3e2-b12a-5c16-a2f0-458d98a43e58', 0, 'instrument', 'callableRangeAccrualData', 'RangeLowerBounds', 'instruments.xsd', '/callableRangeAccrualData/RangeLowerBounds', 20, 'record:stFreeStyleNumberVector', true, 'Range lower bounds', 'The RangeLowerBounds element of callableRangeAccrualData, which the ORE user guide does not describe.', 'The RangeLowerBounds element of callableRangeAccrualData, which the ORE user guide does not describe.', 'None: the trade must give it.', 'A st free style number vector record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'd62b8875-c33c-57a2-8470-d5e1a018fb34', 0, 'instrument', 'callableSwapData', 'OptionData', 'instruments.xsd', '/callableSwapData/OptionData', 0, 'record:optionData', true, 'Option data', 'This is a trade component sub-node outlined in section the guide.', 'This is a trade component sub-node outlined in section the guide. The exercise dates specify the dates on which one of the counterparties may terminate the swap. The counterpart holding the call right is specified by the LongShort flag. The Settlement should be set to Physical always. See also the OptionData node outlined for a Swaption - see the guide, which is identical for a CallableSwap with the exception of the requirement that Settlement must be Physical, and that the leg directions on a CallableSwap are from the perspective of the client, whereas they are from the perspective of the party that is long on a Swaption. A callable swap can be marked as exercised as explained in the guide using the ExerciseData node within OptionData. Note that if an exercise triggers the exchange of notionals in a cross currency callable swap, this exchange must be captured as two exercise fees in the respective currencies.', 'None: the trade must give it.', 'A option data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c4951886-c4d5-53f2-83a4-4522cf556455', 0, 'instrument', 'callableSwapData', 'LegData', 'instruments.xsd', '/callableSwapData/LegData', 1, 'list:legData', true, 'Leg data', 'This is a trade component sub-node described in section the guide outlining each leg of the underlying Swap.', 'This is a trade component sub-node described in section the guide outlining each leg of the underlying Swap. A Callable Swap must have at least one leg on the underlying Swap, but can have multiple legs, i.e. multiple LegData nodes. The LegType elements must be of types Floating, Fixed, Cashflow or RangeAccrual. Cross currency underlyings are supported. Note that the direction of the legs, determined by the Payer tag, is like for a Swap, from the perspective of the party to the trade. I.e. unlike for a Swaption where the direction of the legs is from the perspective of the party that is long.', 'None: the trade must give it.', 'A leg data record, repeated.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1e0a95f1-498f-5518-852a-86d5dbeb6cec', 0, 'instrument', 'callsPutsType', 'LongShorts', 'instruments.xsd', '/callsPutsType/LongShorts', 0, 'record:longShortsType', false, 'Long shorts', 'The LongShorts element of callsPutsType, which the ORE user guide does not describe.', 'The LongShorts element of callsPutsType, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'A long shorts type record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c1e55219-cdbd-5060-9e1f-5efcf92f6ea4', 0, 'instrument', 'callsPutsType', 'Strikes', 'instruments.xsd', '/callsPutsType/Strikes', 1, 'record:strikes', false, 'Strikes', 'The Strikes element of callsPutsType, which the ORE user guide does not describe.', 'The Strikes element of callsPutsType, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'A strikes record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6877e993-ac1c-53ef-8fa4-5a9a765df2b1', 0, 'instrument', 'callsPutsType', 'BarrierData', 'instruments.xsd', '/callsPutsType/BarrierData', 2, 'record:barrierData', false, 'Barrier data', 'The BarrierData element of callsPutsType, which the ORE user guide does not describe.', 'The BarrierData element of callsPutsType, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'A barrier data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '09dc2b90-9011-592a-b32e-06b1b85be245', 0, 'instrument', 'capFloorData', 'LongShort', 'instruments.xsd', '/capFloorData/LongShort', 0, 'string', true, 'Long short', 'This node defines the position in the cap (floor, collar) and can take values Long or Short.', 'This node defines the position in the cap (floor, collar) and can take values Long or Short.', 'None: the trade must give it.', 'One of Long, Short.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '346e2a1a-7f79-516b-85d4-44aa7776dff7', 0, 'instrument', 'capFloorData', 'LegData', 'instruments.xsd', '/capFloorData/LegData', 1, 'record:legData_capfloor', true, 'Leg data', 'This is a trade component sub-node outlined in section the guide.', 'This is a trade component sub-node outlined in section the guide. Exactly one LegData node is allowed, and the LegType element must be set to Floating (Ibor and OIS), CMS, CMSSpread, DurationAdjustedCMS, CPI or YY.', 'None: the trade must give it.', 'A leg data capfloor record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fc2807fd-e6b2-5c10-b6fa-96868f167886', 0, 'instrument', 'capFloorData', 'Caps', 'instruments.xsd', '/capFloorData/Caps', 2, 'record:capFloorData.Caps', false, 'Caps', 'This node has child elements of type Cap capping the floating leg (after applying spread if any).', 'This node has child elements of type Cap capping the floating leg (after applying spread if any). The first rate value corresponds to the first coupon, the second rate value corresponds to the second coupon, etc. If the number of coupons exceeds the number of rate values, the rate will be kept flat at the value of last entered rate for the remaining coupons. For a fixed cap rate over all coupons, one single rate value is sufficient. The number of entered rate values cannot exceed the number of coupons. Allowable values for each Cap element: Any real number. The rate is expressed in decimal form, eg 0.05 is a rate of 5%', 'Not given: ORE applies its own rule.', 'A caps record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5440dd6b-b5d9-572d-b26e-f62c5d4a8ca0', 0, 'instrument', 'capFloorData', 'Floors', 'instruments.xsd', '/capFloorData/Floors', 3, 'record:capFloorData.Floors', false, 'Floors', 'This node has child elements of type Floor flooring the floating leg (after applying spread if any).', 'This node has child elements of type Floor flooring the floating leg (after applying spread if any). The first rate value corresponds to the first coupon, the second rate value corresponds to the second coupon, etc. If the number of coupons exceeds the number of rate values, the rate will be kept flat at the value of last entered rate for the remaining coupons. For a fixed floor rate over all coupons, one single rate value is sufficient. The number of entered rate values cannot exceed the number of coupons. Allowable values for each Floor element: Any real number. The rate is expressed in decimal form, eg 0.05 is a rate of 5%', 'Not given: ORE applies its own rule.', 'A floors record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b851663a-0803-5d00-97dc-b0c99ce2f195', 0, 'instrument', 'capFloorData', 'PremiumAmount', 'instruments.xsd', '/capFloorData/PremiumAmount', 4, 'string', false, 'Premium amount', 'The PremiumAmount element of capFloorData, which the ORE user guide does not describe.', 'The PremiumAmount element of capFloorData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
