        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9b2e6a3c-8ed3-5631-913e-549e77b271dc', 0, 'instrument', 'commodityForwardData', 'Strike', 'instruments.xsd', '/commodityForwardData/Strike', 4, 'double', true, 'Strike', 'The agreed buy/sell price of the commodity forward.', 'The agreed buy/sell price of the commodity forward. \\ Allowable values: Any real number.', 'None: the trade must give it.', 'A number.', '1.8.17.0 or earlier', null),
