        (v_dataset_id, ores_utility_system_tenant_id_fn(), '53952b04-ae3f-5ae5-84d1-fe9547902d1b', 0, 'instrument', 'commodityForwardData', 'IsFuturePrice', 'instruments.xsd', '/commodityForwardData/IsFuturePrice', 6, 'string', false, 'Is future price', 'This should be set to true if the forward contract underlying is the settlement price of a commodity future contract.', 'This should be set to true if the forward contract underlying is the settlement price of a commodity future contract. If omitted, it defaults to false. \\ Allowable values: Any string that evaluates to true or false as outlined in Table the guide.', 'Not given: ORE applies its own rule.', 'One of Y, YES, TRUE, True, true, 1, N, NO, FALSE, False, false, 0, .', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8a9c0f72-ae75-5bba-8671-b530fe606703', 0, 'instrument', 'commodityForwardData', 'FutureExpiryDate', 'instruments.xsd', '/commodityForwardData/FutureExpiryDate', 7, 'string', false, 'Future expiry date', 'If IsFuturePrice is set to true, this gives the expiration date of the underlying commodity future contract.', 'If IsFuturePrice is set to true, this gives the expiration date of the underlying commodity future contract. If omitted, the expiration date of the underlying commodity future contract is set equal to the value in the Maturity node. If FutureExpiryDate is provided, it takes precedence over any value provided in the Maturity, FutureExpiryOffset or FutureExpiryOffsetCalendar fields. \\ Allowable values: Any date string, see Date in Table the guide.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0e187ce2-24ad-5b99-a1e2-ae36517f27b2', 0, 'instrument', 'commodityForwardData', 'FutureExpiryOffset', 'instruments.xsd', '/commodityForwardData/FutureExpiryOffset', 8, 'string', false, 'Future expiry offset', 'If IsFuturePrice is set to true and FutureExpiryDate is not explicitly specified, this gives the offset period that should be applied to the Maturity date to generate the underlying commodity future contract expiration date.', 'If IsFuturePrice is set to true and FutureExpiryDate is not explicitly specified, this gives the offset period that should be applied to the Maturity date to generate the underlying commodity future contract expiration date. If omitted, the expiration date of the underlying commodity future contract is set equal to the value in the Maturity node. \\ Allowable values: Any string that can be parsed as a period e.g.\ 2D, 3M, etc.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0b020189-d6a5-5e73-a86c-28c311162f45', 0, 'instrument', 'commodityForwardData', 'FutureExpiryOffsetCalendar', 'instruments.xsd', '/commodityForwardData/FutureExpiryOffsetCalendar', 9, 'string', false, 'Future expiry offset calendar', 'If FutureExpiryOffset is provided and is being used, this gives the calendar that should be used when generating the underlying commodity future contract expiration date from the Maturity date.', 'If FutureExpiryOffset is provided and is being used, this gives the calendar that should be used when generating the underlying commodity future contract expiration date from the Maturity date. If omitted, all days are considered good business days when generating the commodity future contract expiration date which is generally not what is desired. \\ Allowable values: Any calendar string, see Calendar in Table the guide.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'df0ae0a9-f0cd-5b55-84eb-1c042d47cf43', 0, 'instrument', 'commodityForwardData', 'PhysicallySettled', 'instruments.xsd', '/commodityForwardData/PhysicallySettled', 10, 'string', false, 'Physically settled', 'A value of true indicates that the forward contract is physically settled e.g.\ if the underlying is a future contract, that future contract is entered into on the Maturity date.', 'A value of true indicates that the forward contract is physically settled e.g.\ if the underlying is a future contract, that future contract is entered into on the Maturity date. A value of false indicates that the forward contract is cash settled e.g.\ if the underlying is a future contract, that future contract settlement price is observed on the Maturity date (or the FutureExpiryDate, when given) and the net amount due is exchanged on the cash settlement date. If omitted, it defaults to true. \\ Allowable values: Any string that evaluates to true or false as outlined in Table the guide.', 'Not given: ORE applies its own rule.', 'One of Y, YES, TRUE, True, true, 1, N, NO, FALSE, False, false, 0, .', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1a819f35-8837-5c82-9184-5b2c523000ce', 0, 'instrument', 'commodityForwardData', 'PaymentDate', 'instruments.xsd', '/commodityForwardData/PaymentDate', 11, 'string', false, 'Payment date', 'If PhysicallySettled is set to false, this gives the cash settlement date.', 'If PhysicallySettled is set to false, this gives the cash settlement date. It must be greater than or equal to the Maturity date. If omitted and the forward is cash settled, the Maturity date is used. \\ Allowable values: Any date string, see Date in Table the guide.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f9321fcb-17aa-5abc-8998-86e6efc14a26', 0, 'instrument', 'commodityForwardData', 'SettlementData', 'instruments.xsd', '/commodityForwardData/SettlementData', 12, 'record:commForwardSettlementData', false, 'Settlement data', 'This node is used to specify the settlement of the cash flows for cash settled forwards, and the payment flow for physically settled ones.', 'This node is used to specify the settlement of the cash flows for cash settled forwards, and the payment flow for physically settled ones.', 'Not given: ORE applies its own rule.', 'A comm forward settlement data record.', '1.8.17.0 or earlier', null),
