        (v_dataset_id, ores_utility_system_tenant_id_fn(), '60f1e4d2-182a-5474-bc71-cbb402e22f2b', 0, 'instrument', 'legData_capfloor', 'LegType', 'instruments.xsd', '/legData_capfloor/LegType', 1, 'string', true, 'Leg type', 'Determines which of the available sub-nodes must be used.', 'Determines which of the available sub-nodes must be used. Allowable values: Fixed, Floating, Cashflow, CMS, CMB, DigitalCMS, DurationAdjustedCMS, CMSSpread, DigitalCMSSpread, Equity, CPI, YY, ZeroCouponFixed, FormulaBased, CommodityFloating, CommodityFixed, EquityMargin, RangeAccrual', 'None: the trade must give it.', 'One of Fixed, Floating, CPI, YY, CMS, CMB, DigitalCMS, CMSSpread, DigitalCMSSpread, Cashflow, Equity, FormulaBased, ZeroCouponFixed, IntradayPowerFloating, CommodityFixed, CommodityFloating, EquityMargin, DurationAdjustedCMS, RangeAccrual.', '1.8.17.0 or earlier', null),
