        (v_dataset_id, ores_utility_system_tenant_id_fn(), '04faaee5-f9b2-5799-b1d2-594a18ae662e', 0, 'instrument', 'nameData', 'CreditCurveId', 'instruments.xsd', '/nameData/CreditCurveId', 2, 'string', false, 'Credit curve id', 'The unique identifier of the index component defining one of the default curves used for pricing.', 'The unique identifier of the index component defining one of the default curves used for pricing. The pricing can be set up to either use the curve identifiers of the index components, or one single index curve id defined in the trade specific data. A ReferenceInformation node may be used in place of this CreditCurveId node. Allowable values: See CreditCurveId for credit trades - single name in Table the guide. Duplicate CreditCurveId:s are not allowed. \\', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'f5927e6f-eee5-5ea5-8a56-51f79277ccba', 0, 'instrument', 'nameData', 'ReferenceInformation', 'instruments.xsd', '/nameData/ReferenceInformation', 3, 'record:ReferenceInformation', false, 'Reference information', 'This node may be used as an alternative to the CreditCurveId node to specify the reference entity, tier, currency and documentation clause for the basket constituent.', 'This node may be used as an alternative to the CreditCurveId node to specify the reference entity, tier, currency and documentation clause for the basket constituent. This in turn defines the credit curve used for this basket constituent in the pricing. The ReferenceInformation node is described in further detail in Section the guide.', 'Not given: ORE applies its own rule.', 'A reference information record.', '1.8.17.0 or earlier', null),
