        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ebcb14b7-685a-54ff-bf87-d966932264b2', 0, 'instrument', 'nettingSetDetails', 'LegalEntityId', 'instruments.xsd', '/nettingSetDetails/LegalEntityId', 4, 'string', false, 'Legal entity id', 'The LegalEntityId element of nettingSetDetails, which the ORE user guide does not describe.', 'The LegalEntityId element of nettingSetDetails, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1afac2e8-c106-5709-bfe3-36e623e40221', 0, 'instrument', 'optionData', 'LongShort', 'instruments.xsd', '/optionData/LongShort', 0, 'string', true, 'Long short', 'The allowable values are Long or Short.', 'The allowable values are Long or Short. Note that for Swaptions the payer and receiver legs in the underlying swap are always from the perspective of the party that is Long. E.g. for a Short swaption with a fixed leg where the Payer flag is set to false, it means that the counterparty receives the fixed flows. \begin{table}[H] \centering \begin{tabular} {| c | c | c | c |} \hline LongShort & \makecell{Payer for Fixed leg \\ on underlying Swap} & \makecell{Payer for Floating leg \\ on underlying Swap} & Resulting Set Up and Flows \\ \hline Long & true & false & \makecell[l]{The Party to the trade buys an \\ option to enter a swap where the \\ Party pays fixed and receives \\ floating} \\ \hline Short & true & false & \makecell[l]{The Party to the trade sells an \\ option to the Counterparty to enter \\ a swap where the Counterparty \\ pays fixed and receives floating} \\ \hline Long & false & true & \makecell[l]{The Party to the trade buys an \\ option to enter a swap where the \\ Party receives fixed and pays \\ floating} \\ \hline Short & false & true & \makecell[l]{The Party to the trade sells an \\ option to the Counterparty to enter \\ a swap where the Counterparty \\ receives fixed and pays floating} \\ \hline', 'None: the trade must give it.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4c2b09b0-89c9-528a-8154-dfd89c29762d', 0, 'instrument', 'optionData', 'OptionType', 'instruments.xsd', '/optionData/OptionType', 1, 'string', false, 'Option type', 'This flag is optional for swaptions, and even if set, has no impact.', 'This flag is optional for swaptions, and even if set, has no impact. Whether a swaption is a payer or receiver swaption is determined by the Payer flags on the legs of the underlying swap.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c791138f-f3cf-5a8d-9f0f-8e153b207cef', 0, 'instrument', 'optionData', 'PayoffType', 'instruments.xsd', '/optionData/PayoffType', 2, 'string', false, 'Payoff type', 'The PayoffType element of optionData, which the ORE user guide does not describe.', 'The PayoffType element of optionData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
