        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6aaca59a-f295-5bac-9dfa-363954bd5c84', 0, 'instrument', 'swapData', 'NettingPrecision', 'instruments.xsd', '/swapData/NettingPrecision', 1, 'integer', false, 'Netting precision', 'Number of decimal places to round the total average fixing before multiplying by the quantity.', 'Number of decimal places to round the total average fixing before multiplying by the quantity. Only applies when RoundNettedFloatingLegs is true. If not specified, no rounding is applied to the netted fixing.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9ea265e9-cdc7-5877-aa52-a44676a9ea45', 0, 'instrument', 'swapData', 'Settlement', 'instruments.xsd', '/swapData/Settlement', 2, 'string', false, 'Settlement', 'Delivery type applicable to cross currency swaps, and ignored for all other swap types.', 'Delivery type applicable to cross currency swaps, and ignored for all other swap types. Delivery type does not impact pricing in ORE, but npv results are produced with and without SIMM exemptions. Settlement Cash indicates that principal exchanges on the cross currency swap should be included in Initial Margin (IM). According to ISDA non-deliverable (Cash) trades are excluded from the exemption from IM for the principal exchange, i.e. the principal exchanges are included in IM. Settlement Physical indicates that principal exchanges on the cross currency swap should be excluded in IM (the ISDA exemption applies). Allowable values: Cash or Physical. Defaults to Physical if left blank or omitted.', 'Not given: ORE applies its own rule.', 'One of Physical, Cash.', '1.8.17.0 or earlier', null),
