        (v_dataset_id, ores_utility_system_tenant_id_fn(), '99f1a09e-da55-584c-b8dd-be32efa059f5', 0, 'instrument', 'underlying', 'Type', 'instruments.xsd', '/underlying/Type', 0, 'string', true, 'Type', 'The type of the Underlying asset.', 'The type of the Underlying asset. Allowable values: Equity, FX, Commodity, InterestRate, Inflation, Credit, Bond', 'None: the trade must give it.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7ba9a985-a65c-5829-b431-c33fd3453513', 0, 'instrument', 'underlying', 'Name', 'instruments.xsd', '/underlying/Name', 1, 'string', true, 'Name', 'The name of the Underlying asset.', 'The name of the Underlying asset. Allowable values: Equity: See Name for equity trades in Table the guide FX: A string on the form SOURCE-CCY1-CCY2, where SOURCE is the FX fixing source, and the fixing is expressed as amount in CCY2 per one unit of CCY1. See Table the guide, and note that the FX- prefix is not included in Name as it is already included in Type. InterestRate: Any valid interest rate index name, see Table the guide Inflation: Any valid zero coupon inflation index (CPI) name, See Table the guide Credit: Any valid credit name with a configured default curve, see Table the guide Bond: Any valid bond identifier, the bond must be set up in the reference data. Commodity: An identifier specifying the commodity being referenced in the leg. % The following needs to move into client-specific documentation of allowable values: %The Name is of the form Prefix:Identifier. The Prefix is either PM for precious metal or a code representing the exchange on which the commodity is traded. For precious metals, the Identifier is the precious metal code followed by the precious metal price currency. For future contracts, the Identifier is the exchange code for the future contract. Table the guide lists the allowable values for Name and gives a description. \\', 'None: the trade must give it.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'a1e784d3-ba5c-5762-a35d-e1657ddb6660', 0, 'instrument', 'underlying', 'IdentifierType', 'instruments.xsd', '/underlying/IdentifierType', 2, 'string', false, 'Identifier type', 'Only valid when Type is Equity or Bond.', 'Only valid when Type is Equity or Bond. The type of the identifier being used. Allowable values: RIC, ISIN, FIGI, BBG. Defaults to RIC, if left blank or omitted, and Type: is Equity.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fa860333-d9ec-59d6-a632-31bfb32e6550', 0, 'instrument', 'underlying', 'Currency', 'instruments.xsd', '/underlying/Currency', 3, 'string', false, 'Currency', 'The Currency element of underlying, which the ORE user guide does not describe.', 'The Currency element of underlying, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8033219b-0c0a-5abe-bd23-2bc7e650bcb8', 0, 'instrument', 'underlying', 'Exchange', 'instruments.xsd', '/underlying/Exchange', 4, 'string', false, 'Exchange', 'The Exchange element of underlying, which the ORE user guide does not describe.', 'The Exchange element of underlying, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ddf3d483-c96a-56a2-86de-fbb9fa0e1fb4', 0, 'instrument', 'underlying', 'Weight', 'instruments.xsd', '/underlying/Weight', 5, 'double', false, 'Weight', 'The relative weight of the underlying if part of a basket.', 'The relative weight of the underlying if part of a basket. For a single underlying this can be omitted or set to 1. Allowable values: A real number. Defaults to 1 if left blank or omitted. A value of zero means that the underlying is excluded from the basket. Notes on negative weights in the TotalReturnSwap trade type: Negative weights for EquityOptionPositions are allowed, but not recommended. A negative weight for an EquityOptionPosition is equivalent to inverting the LongShort flag in the respective OptionData node. For EquityPositions a negative weight means that flows are in the opposite direction of the Payer flag on the return leg. A use case for negative weights is for a basket of EquityPositions that include both long and short positions.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '4bbae301-47b1-565d-8e38-88f0751cdc59', 0, 'instrument', 'underlying', 'PriceType', 'instruments.xsd', '/underlying/PriceType', 6, 'string', false, 'Price type', 'Only valid when Type is Commodity.', 'Only valid when Type is Commodity. Whether the Spot or Future price is referenced. Allowable values: Spot, FutureSettlement. Mandatory when Type is Commodity .', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9339deb5-83d4-54a1-9061-67f192954ba6', 0, 'instrument', 'underlying', 'FutureMonthOffset', 'instruments.xsd', '/underlying/FutureMonthOffset', 7, 'integer', false, 'Future month offset', 'Only valid when Type is Commodity.', 'Only valid when Type is Commodity. Only relevant for the FutureSettlement price type, in which case the N+1th future with expiry greater than ObservationDate for the given commodity underlying will be referenced. Allowable values: An integer. Mandatory for when Type is Commodity and PriceType is FutureSettlement.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'bc3fa4bd-0ff2-5e72-ad7c-2c12926ba1db', 0, 'instrument', 'underlying', 'DeliveryRollDays', 'instruments.xsd', '/underlying/DeliveryRollDays', 8, 'integer', false, 'Delivery roll days', 'Only valid when Type is Commodity.', 'Only valid when Type is Commodity. The number of days the observation date is rolled forward before the next future expiry is looked up. Allowable values: An integer. Defaults to 0 if left blank or omitted, and Type: is Commodity.', 'Not given: ORE applies its own rule.', 'A whole number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fe48ff91-b0ca-5afb-9fa7-fe77b09226f9', 0, 'instrument', 'underlying', 'DeliveryRollCalendar', 'instruments.xsd', '/underlying/DeliveryRollCalendar', 9, 'string', false, 'Delivery roll calendar', 'Only valid when Type is Commodity.', 'Only valid when Type is Commodity. The calendar used to roll forward the observation date. Allowable values: See Table the guide. Defaults to the null calendar if left blank or omitted, and Type: is Commodity.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3fc5ca01-eafb-536f-9899-291c74f5de70', 0, 'instrument', 'underlying', 'FutureExpiryDate', 'instruments.xsd', '/underlying/FutureExpiryDate', 10, 'string', false, 'Future expiry date', 'Only valid when Type is Commodity, PriceType is FutureSettlement and there is no FutureContractMonth node.', 'Only valid when Type is Commodity, PriceType is FutureSettlement and there is no FutureContractMonth node. This gives the expiration date of the underlying commodity future contract. If the field FutureExpiryDate and FutureContractMonth are omitted, the expiration date of the underlying commodity future contract is set to the prompt future, adjusted for any FutureMonthOffset.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e5123dc8-c93e-59cc-a86e-fa21a369307e', 0, 'instrument', 'underlying', 'FutureContractMonth', 'instruments.xsd', '/underlying/FutureContractMonth', 11, 'string', false, 'Future contract month', 'Only valid when Type is Commodity, PriceType is FutureSettlement and there is no FutureExpiryDate node.', 'Only valid when Type is Commodity, PriceType is FutureSettlement and there is no FutureExpiryDate node. It specifies the underlying future contract month in the format MonYYYY, for example Nov2023.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b2ddc1d3-3397-529e-ad58-98d51124eebf', 0, 'instrument', 'underlying', 'Interpolation', 'instruments.xsd', '/underlying/Interpolation', 12, 'string', false, 'Interpolation', 'Only valid when Type is Inflation.', 'Only valid when Type is Inflation. The index observation interpolation between fixings. Allowable values: Flat, Linear', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8a400923-78cb-5a1e-94f2-8f89fc5cab26', 0, 'instrument', 'underlying', 'BidAskAdjustment', 'instruments.xsd', '/underlying/BidAskAdjustment', 13, 'double', false, 'Bid ask adjustment', 'Only valid when Type is Bond.', 'Only valid when Type is Bond. A correction applied to the price found in the market data (usually mid), if the bond basket price is defined on the bid or ask side rather than mid. Allowable values: Any real number.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.17.0 or earlier', null),
