        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'fe84f2b6-8344-5052-b3e5-048c2a31a728', 0, 'instrument', 'varianceSwapData', 'Name', 'instruments.xsd', '/varianceSwapData/Name', 3, 'string', false, 'Name', 'The identifier of the underlying equity or equity index.', 'The identifier of the underlying equity or equity index. \\ Allowable values: See Name for equity trades in Table the guide. \\', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e00cc4c2-e56b-5ccb-9c1a-882bd5a1249e', 0, 'instrument', 'varianceSwapData', 'Underlying', 'instruments.xsd', '/varianceSwapData/Underlying', 4, 'record:underlying', false, 'Underlying', 'This node may be used as an alternative to the Name node to specify the underlying equity.', 'This node may be used as an alternative to the Name node to specify the underlying equity. This in turn defines the equity curve used for pricing. The Underlying node is described in further detail in Section the guide. \\', 'Not given: ORE applies its own rule.', 'A underlying record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ac8ed840-7a60-5ef1-9814-6048872e4b48', 0, 'instrument', 'varianceSwapData', 'Underlyings', 'instruments.xsd', '/varianceSwapData/Underlyings', 5, 'record:underlyings', false, 'Underlyings', 'The Underlyings element of varianceSwapData, which the ORE user guide does not describe.', 'The Underlyings element of varianceSwapData, which the ORE user guide does not describe.', 'Not given: ORE applies its own rule.', 'A underlyings record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '3b4cf31d-eab0-5af4-9a7b-2ba5f71c8126', 0, 'instrument', 'varianceSwapData', 'LongShort', 'instruments.xsd', '/varianceSwapData/LongShort', 6, 'string', true, 'Long short', 'Defines whether the trade is long in the equity variance.', 'Defines whether the trade is long in the equity variance. For the avoidance of doubt, a long variance swap has positive value if the realised variance exceeds the variance strike. \\ Allowable values: Long, Short', 'None: the trade must give it.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '9c4db659-877e-55cf-97bd-64a8150a7b34', 0, 'instrument', 'varianceSwapData', 'Strike', 'instruments.xsd', '/varianceSwapData/Strike', 7, 'double', true, 'Strike', 'The volatility strike K_{vol} of the variance swap quoted absolutely (i.e.', 'The volatility strike K_{vol} of the variance swap quoted absolutely (i.e. not as a percent). If the swap was struck in terms of variance, the square root of that variance should be used here.\\ Allowable values: Any positive real number.', 'None: the trade must give it.', 'A number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '368b8b4f-89e9-5bb5-a73d-2b77717fe648', 0, 'instrument', 'varianceSwapData', 'Notional', 'instruments.xsd', '/varianceSwapData/Notional', 8, 'double', true, 'Notional', 'The vega notional of the variance swap.', 'The vega notional of the variance swap. This is the notional in terms of volatility units (like the strike). If the swap was struck in terms of a variance notional N_{var}, the corresponding vega notional is given by N_{vol} = N_{var} * 2 * 100 * K_{vol} (where K_{vol} is in absolute terms).\\ Allowable values: Any non-negative real number.', 'None: the trade must give it.', 'A number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '088a743c-ec05-5344-a832-a956a699a96a', 0, 'instrument', 'varianceSwapData', 'Calendar', 'instruments.xsd', '/varianceSwapData/Calendar', 9, 'string', true, 'Calendar', 'The calendar determining the observation/fixing dates according to which variance is accrued is the combination of the calendar(s) given here plus the calendar associated with the equity in the equity curve configuration.', 'The calendar determining the observation/fixing dates according to which variance is accrued is the combination of the calendar(s) given here plus the calendar associated with the equity in the equity curve configuration. If no such calendar is given in the equity curve configuration the standard calendar for the equity currency (also defined in the curve config) is used instead. \\ Allowable values: See Table the guide.', 'None: the trade must give it.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1c76e2d0-f3c6-5e0e-8b7c-2097a78f4958', 0, 'instrument', 'varianceSwapData', 'MomentType', 'instruments.xsd', '/varianceSwapData/MomentType', 10, 'string', false, 'Moment type', 'A flag to distinguish if the swap is struck in terms of volatility or variance.', 'A flag to distinguish if the swap is struck in terms of volatility or variance. The MomentType should be set to Volatility or Variance depending on the payoff. Note that MomentType does not necessarily need to be equivalent to the way the Strike is quoted which is always as a Volatility. \\ Allowable values: Volatility or Variance. Defaults to Variance if left blank or omitted.', 'Not given: ORE applies its own rule.', 'One of Variance, Volatility.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c10daee8-8bc3-58ac-973d-59c6bd6cb8c4', 0, 'instrument', 'varianceSwapData', 'AddPastDividends', 'instruments.xsd', '/varianceSwapData/AddPastDividends', 11, 'boolean', false, 'Add past dividends', 'A flag to distinguish if past dividend payments should be added to the fixings when calculating accrued variance.', 'A flag to distinguish if past dividend payments should be added to the fixings when calculating accrued variance. \\ Allowable values: true or false. Defaults to false if left blank or omitted.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
