        (v_dataset_id, ores_utility_system_tenant_id_fn(), '10bef46c-41db-5032-8182-6eccbf8c4a89', 0, 'instrument', 'worstOfBasketSwapData2', 'FloatingFixingSchedule', 'instruments.xsd', '/worstOfBasketSwapData2/FloatingFixingSchedule', 9, 'record:scheduleData', false, 'Floating fixing schedule', 'Fixing dates for floating coupons linked to Ibor indices.', 'Fixing dates for floating coupons linked to Ibor indices. The d^\text{th} date in this schedule is the fixing date for the (d+1)^\text{th} date in the FloatingPayDates. For floating coupons linked to overnight indices this scheulde is not relevant, the fixing dates are derived from the FloatingPeriodScheudle and FloatingLookback. \\ Allowable values: See section the guide Schedule Data and Dates/Rules, or DerivedSchedule for scripted trades (see the Event data structure in ore/Docs/ScriptedTrade). If left blank or omitted, defaults to a DerivedSchedule with the FloatingPeriodSchedule set as the base schedule.', 'Not given: ORE applies its own rule.', 'A schedule data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '6def6b4e-12f9-5fac-90c6-10e1e9b9ad73', 0, 'instrument', 'worstOfBasketSwapData2', 'FixedDeterminationSchedule', 'instruments.xsd', '/worstOfBasketSwapData2/FixedDeterminationSchedule', 10, 'record:scheduleData', false, 'Fixed determination schedule', 'If AccruingFixedCoupons is False, the observation dates on which a fixed trigger event is evaluated, upon which a fixed coupon payout is made.', 'If AccruingFixedCoupons is False, the observation dates on which a fixed trigger event is evaluated, upon which a fixed coupon payout is made. Otherwise, there is no payout. If AccruingFixedCoupons is True, these will be the dates on which fixed coupon amounts are calculated. The coupon amount is scaled by the number of fixed trigger days relative to the total number of days in the period. \\ Allowable values: See section the guide Schedule Data and Dates/Rules, or DerivedSchedule for scripted trades (see the Event data structure in ore/Docs/ScriptedTrade). If left blank or omitted, defaults to a DerivedSchedule with the FloatingPeriodSchedule set as the base schedule.', 'Not given: ORE applies its own rule.', 'A schedule data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '63341fc3-6b46-50ca-8847-e5cb02a22c18', 0, 'instrument', 'worstOfBasketSwapData2', 'FloatingPayDates', 'instruments.xsd', '/worstOfBasketSwapData2/FloatingPayDates', 11, 'record:scheduleData', true, 'Floating pay dates', 'Floating coupon payment dates.', 'Floating coupon payment dates. \\ Allowable values: See section the guide Schedule Data and Dates, Rules, or DerivedSchedule (see ore/Docs/ScriptedTrade).', 'None: the trade must give it.', 'A schedule data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'b58907b0-fbec-5941-8074-db0d708ffaca', 0, 'instrument', 'worstOfBasketSwapData2', 'FixedPayDates', 'instruments.xsd', '/worstOfBasketSwapData2/FixedPayDates', 12, 'record:scheduleData', false, 'Fixed pay dates', 'Fixed coupon payment dates.', 'Fixed coupon payment dates. \\ Allowable values: See section the guide Schedule Data and Dates/Rules, or DerivedSchedule for scripted trades (see the Event data structure in ore/Docs/ScriptedTrade). If left blank or omitted, defaults to the FloatingPayDates.', 'Not given: ORE applies its own rule.', 'A schedule data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '378b258a-bbc0-5933-b176-423a6ae565c5', 0, 'instrument', 'worstOfBasketSwapData2', 'KnockOutDeterminationSchedule', 'instruments.xsd', '/worstOfBasketSwapData2/KnockOutDeterminationSchedule', 13, 'record:scheduleData', false, 'Knock out determination schedule', 'Dates on which a knock-out event is evaluated, after which the instrument is considered to be terminated and no payout is made.', 'Dates on which a knock-out event is evaluated, after which the instrument is considered to be terminated and no payout is made. \\ Allowable values: See section the guide Schedule Data and Dates/Rules, or DerivedSchedule for scripted trades (see the Event data structure in ore/Docs/ScriptedTrade). If left blank or omitted, defaults to a DerivedSchedule with the FloatingPeriodSchedule set as the base schedule.', 'Not given: ORE applies its own rule.', 'A schedule data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '8d7b9ccc-c40a-5aba-92c3-6c0071b656f9', 0, 'instrument', 'worstOfBasketSwapData2', 'FixedAccrualSchedule', 'instruments.xsd', '/worstOfBasketSwapData2/FixedAccrualSchedule', 14, 'record:scheduleData', false, 'Fixed accrual schedule', 'The fixed coupon paid out for each determination date in the FixedDeterminationSchedule is scaled according to the number of days in the FixedAccrualSchedule for which a fixed trigger event occurred, as a fraction of the total number of days in the period (defined by the FixedDeterminationSchedule).', 'The fixed coupon paid out for each determination date in the FixedDeterminationSchedule is scaled according to the number of days in the FixedAccrualSchedule for which a fixed trigger event occurred, as a fraction of the total number of days in the period (defined by the FixedDeterminationSchedule). If AccruingFixedCoupons is True, this node is required. \\ Allowable values: See section the guide Schedule Data and Dates/Rules, or DerivedSchedule for scripted trades (see the Event data structure in ore/Docs/ScriptedTrade).', 'Not given: ORE applies its own rule.', 'A schedule data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '98c9335a-315e-59bb-b113-2fa978518457', 0, 'instrument', 'worstOfBasketSwapData2', 'KnockOutLevels', 'instruments.xsd', '/worstOfBasketSwapData2/KnockOutLevels', 15, 'record:worstOfBasketSwapData2.KnockOutLevels', true, 'Knock out levels', 'For each determination date in KnockOutDeterminationSchedule except for the first date, the barrier level used to determine whether a knock-out trigger event has occurred, resulting in a knock-out (i.e.\ contract termination).', 'For each determination date in KnockOutDeterminationSchedule except for the first date, the barrier level used to determine whether a knock-out trigger event has occurred, resulting in a knock-out (i.e.\ contract termination). \\ Allowable values: For each knock-out determination date, a KnockOutLevel sub-node with any positive number, as a percentage of the initial prices, expressed in decimal form.', 'None: the trade must give it.', 'A knock out levels record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ad73bb59-d64c-507f-bfb0-23a68f155206', 0, 'instrument', 'worstOfBasketSwapData2', 'BermudanKnockIn', 'instruments.xsd', '/worstOfBasketSwapData2/BermudanKnockIn', 16, 'boolean', false, 'Bermudan knock in', 'Whether the knock-in event is observed on a regular basis (True), as defined by the KnockInDeterminationSchedule, or only at the final date in the FloatingPeriodSchedule (False).', 'Whether the knock-in event is observed on a regular basis (True), as defined by the KnockInDeterminationSchedule, or only at the final date in the FloatingPeriodSchedule (False). \\ Allowable values: Boolean node, allowing Y, N, 1, 0, true, false, etc. The full set of allowable values is given in Table the guide. If left blank or omitted, defaults to False.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'da0324af-6888-59d2-a975-40c77691c311', 0, 'instrument', 'worstOfBasketSwapData2', 'FixedTriggerLevels', 'instruments.xsd', '/worstOfBasketSwapData2/FixedTriggerLevels', 17, 'record:worstOfBasketSwapData2.FixedTriggerLevels', true, 'Fixed trigger levels', 'For each fixed trigger determination date, the barrier level used to determine whether a coupon trigger event has occurred, upon which a fixed coupon is paid out at the corresponding payment date.', 'For each fixed trigger determination date, the barrier level used to determine whether a coupon trigger event has occurred, upon which a fixed coupon is paid out at the corresponding payment date. \\ Allowable values: For each fixed trigger evaluation date, a FixedTriggerLevel sub-node with any positive number, as a percentage of the initial prices expressed in decimal form.', 'None: the trade must give it.', 'A fixed trigger levels record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '383ecef1-2b1c-5289-bf96-4b94b2668f76', 0, 'instrument', 'worstOfBasketSwapData2', 'KnockInLevel', 'instruments.xsd', '/worstOfBasketSwapData2/KnockInLevel', 18, 'double', false, 'Knock in level', 'The barrier level used to determine whether a knock-in event has occurred for the given knock-in observation date/s, upon which the equity amount is payable at the KnockInPayDate, subject to no knock-out event having occurred over the life of the contract.', 'The barrier level used to determine whether a knock-in event has occurred for the given knock-in observation date/s, upon which the equity amount is payable at the KnockInPayDate, subject to no knock-out event having occurred over the life of the contract. \\ Allowable values: Any number, as a percentage of the initial prices expressed in decimal form.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'c20fa675-0f1e-572d-ac51-cff449a5114a', 0, 'instrument', 'worstOfBasketSwapData2', 'KnockInDeterminationSchedule', 'instruments.xsd', '/worstOfBasketSwapData2/KnockInDeterminationSchedule', 19, 'record:scheduleData', false, 'Knock in determination schedule', 'Observation dates for determining if a knock-in event has occurred.', 'Observation dates for determining if a knock-in event has occurred. If BermudanKnockIn is True, this node is required. \\ Allowable values: See section the guide Schedule Data and Dates/Rules, or DerivedSchedule for scripted trades (see the Event data structure in ore/Docs/ScriptedTrade).', 'Not given: ORE applies its own rule.', 'A schedule data record.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2569013b-ac87-5410-a30a-534095e4c68e', 0, 'instrument', 'worstOfBasketSwapData2', 'FixedRate', 'instruments.xsd', '/worstOfBasketSwapData2/FixedRate', 20, 'double', true, 'Fixed rate', 'Rate of the fixed coupon leg.', 'Rate of the fixed coupon leg. \\ Allowable values: Any number, as a percentage expressed in decimal form.', 'None: the trade must give it.', 'A number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'efd901b4-bdc9-5245-978e-55562de5544f', 0, 'instrument', 'worstOfBasketSwapData2', 'AccumulatingFixedCoupons', 'instruments.xsd', '/worstOfBasketSwapData2/AccumulatingFixedCoupons', 21, 'boolean', false, 'Accumulating fixed coupons', 'Whether the fixed coupons are accumulating or not.', 'Whether the fixed coupons are accumulating or not. \\ Allowable values: Boolean node, allowing Y, N, 1, 0, true, false, etc. The full set of allowable values is given in Table the guide. If left blank or omitted, defaults to False.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '1015e22f-c204-5641-819a-793cc1306d65', 0, 'instrument', 'worstOfBasketSwapData2', 'AccruingFixedCoupons', 'instruments.xsd', '/worstOfBasketSwapData2/AccruingFixedCoupons', 22, 'boolean', false, 'Accruing fixed coupons', 'Whether the fixed coupons are paid out on an accrual basis (True), or subject to a single fixed trigger event (given by the FixedDeterminationSchedule).', 'Whether the fixed coupons are paid out on an accrual basis (True), or subject to a single fixed trigger event (given by the FixedDeterminationSchedule). \\ Allowable values: Boolean node, allowing Y, N, 1, 0, true, false, etc. The full set of allowable values is given in Table the guide. If left blank or omitted, defaults to False.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e8db4eb2-ddbd-552c-8ada-77b0c631d84e', 0, 'instrument', 'worstOfBasketSwapData2', 'FloatingIndex', 'instruments.xsd', '/worstOfBasketSwapData2/FloatingIndex', 23, 'string', true, 'Floating index', 'Underlying index of the floating leg.', 'Underlying index of the floating leg. \\ Allowable values: See ore/Docs/ScriptedTrade (section Data Node / Index). This must be an InterestRate underlying. Overnight indices are not supported.', 'None: the trade must give it.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '0e184960-6fe9-5d5f-aac8-e769037d5ac5', 0, 'instrument', 'worstOfBasketSwapData2', 'FloatingSpread', 'instruments.xsd', '/worstOfBasketSwapData2/FloatingSpread', 24, 'double', false, 'Floating spread', 'Spread on the floating rate.', 'Spread on the floating rate. \\ Allowable values: Any number. If left blank or omitted, defaults to zero.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '2957107b-0ee7-56b5-943d-cfe0626f8e53', 0, 'instrument', 'worstOfBasketSwapData2', 'FloatingLookback', 'instruments.xsd', '/worstOfBasketSwapData2/FloatingLookback', 25, 'string', false, 'Floating lookback', 'Only applicable when the floating leg reference rate is an overnight index.', 'Only applicable when the floating leg reference rate is an overnight index. The shift applied to each value date in FloatingFixingSchedule to obtain the fixing reference date. \\ Allowable values: Any period definition in unit "Days" (e.g.\ 2D, 30D, but not 1M). If omitted or left blank, defaults to 0D.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '298814fe-681b-5374-9ead-b479ff32d564', 0, 'instrument', 'worstOfBasketSwapData2', 'FloatingRateCutoff', 'instruments.xsd', '/worstOfBasketSwapData2/FloatingRateCutoff', 26, 'string', false, 'Floating rate cutoff', 'Only applicable when the floating leg reference rate is an overnight index.', 'Only applicable when the floating leg reference rate is an overnight index. The number of fixing dates at the end of the fixing period for which the fixing value is held constant and set to the previous value. \\ Allowable values: Any non-negative whole number. If left blank or omitted, defaults to zero.', 'Not given: ORE applies its own rule.', 'Text.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'ae6d4c8a-58ee-5448-a3f9-aa88265acd27', 0, 'instrument', 'worstOfBasketSwapData2', 'FloatingDayCountFraction', 'instruments.xsd', '/worstOfBasketSwapData2/FloatingDayCountFraction', 27, 'string', true, 'Floating day count fraction', 'The day count fraction for the floating leg accrual calculations.', 'The day count fraction for the floating leg accrual calculations. \\ Allowable values: See DayCount Convention in Table the guide.', 'None: the trade must give it.', 'One of A360, Actual/360, ACT/360, Act/360, A360 (Incl Last), Actual/360 (Incl Last), ACT/360 (Incl Last), A365, A365F, Actual/365 (Fixed), Actual/365 (fixed), ACT/365.FIXED, ACT/365, ACT/365L, Act/365, Act/365L, Act/365 (Canadian Bond), T360, 30/360, 30/360 US, 30/360 (US), 30/360 NASD, 30U/360, 30US/360, 30/360 (Bond Basis), ACT/nACT, 30E/360 (Eurobond Basis), 30/360 AIBD (Euro), 30E/360.ICMA, 30E/360 ICMA, 30E/360, 30E/360E, 30E/360.ISDA, 30E/360 ISDA, 30/360 German, 30/360 (German), 30/360 Italian, 30/360 (Italian), ActActISDA, ACT/ACT.ISDA, Actual/Actual (ISDA), ActualActual (ISDA), ACT/ACT, Act/Act, ACT29, ACT, ActActISMA, Actual/Actual (ISMA), ActualActual (ISMA), ACT/ACT.ISMA, ActActICMA, Actual/Actual (ICMA), ActualActual (ICMA), ACT/ACT.ICMA, ActActAFB, ACT/ACT.AFB, Actual/Actual (AFB), 1/1, BUS/252, Business/252, Actual/365 (No Leap), Act/365 (NL), NL/365, Actual/365 (JGB), Simple, Year, A364, Actual/364, Act/364, ACT/364, Month.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '5d5f518b-2e1c-5cfb-8bfd-1fbdb541cc55', 0, 'instrument', 'worstOfBasketSwapData2', 'IsAveraged', 'instruments.xsd', '/worstOfBasketSwapData2/IsAveraged', 28, 'boolean', false, 'Is averaged', 'Only applicable when the floating leg reference rate is an overnight index (where there are multiple fixings over a period).', 'Only applicable when the floating leg reference rate is an overnight index (where there are multiple fixings over a period). If True, the average of the fixings is used to calculate the coupon. If False, the coupon is calculated by compounding the fixings. \\ Allowable values: Boolean node, allowing Y, N, 1, 0, true, false, etc. The full set of allowable values is given in Table the guide. Defaults to false If left blank or omiited.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), '7ff27a7b-44d4-5d2d-acfb-8545767c3bdf', 0, 'instrument', 'worstOfBasketSwapData2', 'IncludeSpread', 'instruments.xsd', '/worstOfBasketSwapData2/IncludeSpread', 29, 'boolean', false, 'Include spread', 'Only applicable when the floating leg reference rate is an overnight index and if IsAveraged is false, i.e.\ the coupon rate is compounded.', 'Only applicable when the floating leg reference rate is an overnight index and if IsAveraged is false, i.e.\ the coupon rate is compounded. If true the spread is included in the compounding, otherwise it is excluded. \\ Allowable values: Boolean node, allowing Y, N, 1, 0, true, false, etc. The full set of allowable values is given in Table the guide.', 'Not given: ORE applies its own rule.', 'true or false.', '1.8.17.0 or earlier', null),
        (v_dataset_id, ores_utility_system_tenant_id_fn(), 'e55f10fb-b76d-5835-a8f9-9dd69e40b06e', 0, 'instrument', 'worstOfBasketSwapData2', 'Strike', 'instruments.xsd', '/worstOfBasketSwapData2/Strike', 30, 'double', false, 'Strike', 'Strike price for each underlying in the basket.', 'Strike price for each underlying in the basket. When calculating the equity amount, this is the price used to calculate the number of shares (for Equity underlyings) owing of the worst-performing asset. \\ Allowable values: Any number, as a percentage of the initial prices, expressed in decimal form. If left blank or omitted, defaults to one, i.e.\ the initial price of the underlying.', 'Not given: ORE applies its own rule.', 'A number.', '1.8.17.0 or earlier', null),
